window.SF_EXAMPLES = [{"id": "solid", "label": "Example 1.1", "title": "Every pixel gives the same answer", "chapter": 1, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    fragColor = vec4(1.0, 0.5, 0.0, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "first-ramp", "label": "Example 1.2", "title": "Each pixel uses its own position", "chapter": 1, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    // fragCoord.x is this pixel's x position, in pixels.\n    // iResolution.x is the width of the canvas, in pixels.\n    float red = fragCoord.x / iResolution.x;   // 0 at the left edge, 1 at the right\n\n    fragColor = vec4(red, 0.0, 0.0, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "both-ramps", "label": "Example 1.3", "title": "Position as color, in both directions", "chapter": 1, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    float red   = fragCoord.x / iResolution.x;   // left 0 → right 1\n    float green = fragCoord.y / iResolution.y;   // bottom 0 → top 1\n\n    fragColor = vec4(red, green, 0.0, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "clamped", "label": "Example 1.4", "title": "Brightness past 1.0 just stays at full", "chapter": 1, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    // Divide by 200 instead of the width: past 200 pixels this goes above 1.0.\n    float red = fragCoord.x / 200.0;\n\n    fragColor = vec4(red, 0.0, 0.0, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "int-float", "label": "Example 2.1", "title": "int() drops the fraction, float() converts back", "chapter": 2, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    float x = fragCoord.x / iResolution.x;   // 0.0 → 1.0 across the canvas\n\n    int column = int(x * 8.0);               // 0, 1, 2 … 7: the fraction is dropped\n    float shade = float(column) / 7.0;       // back to a float: 0.0, 0.14 … 1.0\n\n    fragColor = vec4(shade, shade, shade, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "arith", "label": "Example 2.2", "title": "Arithmetic on a ramp, one calculation per band", "chapter": 2, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    float x = fragCoord.x / iResolution.x;   // 0 → 1 across\n    float y = fragCoord.y / iResolution.y;   // 0 → 1 up\n\n    float flipped = 1.0 - x;     // 1 → 0: bright on the left\n    float shifted = x + 0.25;    // 0.25 → 1.25: never black, reaches white early\n    float doubled = x * 2.0;     // 0 → 2: reaches white halfway across\n\n    float v = flipped;               // bottom band\n    if (y > 0.333) v = shifted;      // middle band\n    if (y > 0.666) v = doubled;      // top band\n\n    fragColor = vec4(v, v, v, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "vec-build", "label": "Example 2.3", "title": "Building bigger vectors from smaller ones", "chapter": 2, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.xy;   // x / width and y / height in one go\n\n    vec3 col = vec3(uv, 0.5);               // red = uv.x, green = uv.y, blue = 0.5\n    fragColor = vec4(col, 1.0);             // plus alpha makes the vec4 the runner wants\n}", "buffer": null}, "cfg": {}}, {"id": "swizzle", "label": "Example 2.4", "title": "One color, four swizzles", "chapter": 2, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.xy;\n    vec3 col = vec3(uv.x, uv.y, 0.2);\n\n    float column = floor(uv.x * 4.0);      // 0, 1, 2 or 3: which quarter of the canvas\n    if (column == 1.0) col = col.bgr;      // reversed\n    if (column == 2.0) col = col.gbr;      // rotated\n    if (column == 3.0) col = col.ggg;      // just green, shown as grey\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "componentwise", "label": "Example 2.5", "title": "Multiplying colors is filtering light", "chapter": 2, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.xy;\n\n    vec3 light = vec3(1.0, 0.9, 0.7);        // warm white light\n    vec3 glass = vec3(0.2, 0.6, 1.0);        // blue glass: lets through 20% red, 60% green, all blue\n\n    vec3 col = light;                        // left half: just the light\n    if (uv.x > 0.5) col = light * glass;     // right half: light through the glass, slot by slot\n\n    col *= uv.y;                             // a vec3 times a float: darker toward the bottom\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "functions", "label": "Example 2.6", "title": "A function we wrote ourselves", "chapter": 2, "passes": {"image": "// Give it a value from 0 to 1, get back a color from cold blue to hot orange.\nvec3 heat(float t) {\n    vec3 cold = vec3(0.1, 0.2, 0.8);\n    vec3 hot  = vec3(1.0, 0.6, 0.1);\n    return cold + (hot - cold) * t;   // at t = 0: cold. At t = 1: cold + hot - cold = hot.\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    float t = fragCoord.x / iResolution.x;\n    fragColor = vec4(heat(t), 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "loop", "label": "Example 2.7", "title": "A loop builds a staircase of ten steps", "chapter": 2, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    float y = fragCoord.y / iResolution.y;\n\n    float brightness = 0.0;\n    for (int i = 0; i < 10; i++) {             // i = 0, 1, 2 … 9\n        if (y > float(i) / 10.0) {             // am I above line i?\n            brightness += 0.1;                 // then one step brighter\n        }\n    }\n\n    fragColor = vec4(vec3(brightness), 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "uv", "label": "Example 3.1", "title": "uv: 0 to 1 across, 0 to 1 up", "chapter": 3, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.xy;   // (x / width, y / height)\n\n    // show uv as color: red = how far across, green = how far up\n    fragColor = vec4(uv.x, uv.y, 0.0, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "remap", "label": "Example 3.2", "title": "-1 to 1: negative numbers are invisible", "chapter": 3, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.xy;   // 0 → 1\n    vec2 p = uv * 2.0 - 1.0;                // -1 → 1, with 0 in the middle\n\n    fragColor = vec4(p.x, p.y, 0.0, 1.0);   // negative values show as black\n    // fragColor = vec4(-p.x, -p.y, 0.0, 1.0);   // try this: now only the other corner shows\n}", "buffer": null}, "cfg": {}}, {"id": "quadrants", "label": "Example 3.3", "title": "Positive x in red, negative x in blue", "chapter": 3, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 p = fragCoord / iResolution.xy * 2.0 - 1.0;   // -1 → 1\n\n    float right = max(p.x, 0.0);    // how far right of center (0 on the left half)\n    float left  = max(-p.x, 0.0);   // how far left of center (0 on the right half)\n    float up    = max(p.y, 0.0);\n\n    fragColor = vec4(right, up * 0.6, left, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "ellipse", "label": "Example 3.4", "title": "A circle in -1..1 coordinates comes out squashed", "chapter": 3, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 p = fragCoord / iResolution.xy * 2.0 - 1.0;   // -1 → 1 in both directions\n\n    float inside = length(p) < 0.5 ? 1.0 : 0.0;       // is this pixel near the center?\n\n    fragColor = vec4(vec3(inside), 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "round", "label": "Example 3.5", "title": "Centered and aspect-correct: a real circle", "chapter": 3, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    // (0,0) in the middle, y from -1 to 1, x scaled by the same amount\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n\n    float inside = length(uv) < 0.5 ? 1.0 : 0.0;\n\n    fragColor = vec4(vec3(inside), 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "coord-viewer", "label": "Example 3.6", "title": "A viewer for centered coordinates", "chapter": 3, "passes": {"image": "// Grid lines every 0.25 units, thicker axes, and the circle of radius 1.\nfloat gridLine(float v, float spacing, float width) {\n    float d = abs(fract(v / spacing + 0.5) - 0.5) * spacing;   // distance to the nearest line\n    return 1.0 - smoothstep(0.0, width, d);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    float px = 2.0 / iResolution.y;                  // the size of one pixel in these units\n\n    // quadrants: tint by the signs of x and y\n    vec3 col = vec3(0.08, 0.09, 0.12);\n    col += vec3(0.25, 0.08, 0.0) * step(0.0, uv.x);  // a little orange where x > 0\n    col += vec3(0.0, 0.08, 0.25) * step(0.0, uv.y);  // a little blue where y > 0\n\n    float g = max(gridLine(uv.x, 0.25, px), gridLine(uv.y, 0.25, px));\n    col = mix(col, vec3(0.35), g);\n\n    float axes = max(1.0 - smoothstep(0.0, 2.0 * px, abs(uv.x)), 1.0 - smoothstep(0.0, 2.0 * px, abs(uv.y)));\n    col = mix(col, vec3(0.9), axes);\n\n    float ring = 1.0 - smoothstep(0.0, 2.0 * px, abs(length(uv) - 1.0));\n    col = mix(col, vec3(1.0, 0.65, 0.2), ring);\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "mouse", "label": "Example 3.7", "title": "A disc that follows the mouse (drag on the canvas)", "chapter": 3, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    vec2 m  = (iMouse.xy * 2.0 - iResolution.xy) / iResolution.y;   // same conversion\n\n    float inside = length(uv - m) < 0.25 ? 1.0 : 0.0;   // distance from this pixel to the mouse\n\n    vec3 col = mix(vec3(0.1, 0.12, 0.18), vec3(1.0, 0.6, 0.2), inside);\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "plot-x", "label": "Example 4.1", "title": "A function plotter, showing f(x) = x", "chapter": 4, "passes": {"image": "// The function to draw. Change it!\nfloat f(float x) {\n    return x;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    // View: centered on (0.5, 0.5), y from -0.2 to 1.2, x a little wider.\n    vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y * 1.4 + 0.5;\n    float px = 1.4 / iResolution.y;                  // the size of one pixel in these units\n\n    vec3 col = vec3(0.07, 0.08, 0.1);\n    vec2 g = abs(fract(p * 10.0 + 0.5) - 0.5) / 10.0;               // faint grid every 0.1\n    col += 0.06 * (1.0 - smoothstep(0.0, px, min(g.x, g.y)));\n    vec2 a = min(abs(p), abs(p - 1.0));                             // brighter lines at 0 and 1\n    col += 0.25 * (1.0 - smoothstep(0.0, 1.5 * px, min(a.x, a.y)));\n\n    // How far is this pixel from the curve? (vertical gap, corrected for steepness)\n    float y = f(p.x);\n    float slope = (f(p.x + px) - f(p.x - px)) / (2.0 * px);\n    float d = abs(p.y - y) / sqrt(1.0 + slope * slope);\n    col = mix(col, vec3(1.0, 0.65, 0.2), 1.0 - smoothstep(0.0, 2.0 * px, d));\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "plot-linear", "label": "Example 4.2", "title": "f(x) = 2x − 0.5: twice as steep, shifted down", "chapter": 4, "passes": {"image": "float f(float x) {\n    return 2.0 * x - 0.5;   // slope 2, offset -0.5\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y * 1.4 + 0.5;\n    float px = 1.4 / iResolution.y;\n    vec3 col = vec3(0.07, 0.08, 0.1);\n    vec2 g = abs(fract(p * 10.0 + 0.5) - 0.5) / 10.0;\n    col += 0.06 * (1.0 - smoothstep(0.0, px, min(g.x, g.y)));\n    vec2 a = min(abs(p), abs(p - 1.0));\n    col += 0.25 * (1.0 - smoothstep(0.0, 1.5 * px, min(a.x, a.y)));\n    float y = f(p.x);\n    float slope = (f(p.x + px) - f(p.x - px)) / (2.0 * px);\n    float d = abs(p.y - y) / sqrt(1.0 + slope * slope);\n    col = mix(col, vec3(1.0, 0.65, 0.2), 1.0 - smoothstep(0.0, 2.0 * px, d));\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "plot-pow", "label": "Example 4.3", "title": "f(x) = pow(x, 2.0): a slow start", "chapter": 4, "passes": {"image": "float f(float x) {\n    return pow(x, 2.0);    // try 0.5, 3.0, 8.0. Then try x * x and compare left of 0.\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y * 1.4 + 0.5;\n    float px = 1.4 / iResolution.y;\n    vec3 col = vec3(0.07, 0.08, 0.1);\n    vec2 g = abs(fract(p * 10.0 + 0.5) - 0.5) / 10.0;\n    col += 0.06 * (1.0 - smoothstep(0.0, px, min(g.x, g.y)));\n    vec2 a = min(abs(p), abs(p - 1.0));\n    col += 0.25 * (1.0 - smoothstep(0.0, 1.5 * px, min(a.x, a.y)));\n    float y = f(p.x);\n    float slope = (f(p.x + px) - f(p.x - px)) / (2.0 * px);\n    float d = abs(p.y - y) / sqrt(1.0 + slope * slope);\n    col = mix(col, vec3(1.0, 0.65, 0.2), 1.0 - smoothstep(0.0, 2.0 * px, d));\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "plot-step", "label": "Example 4.4", "title": "f(x) = step(0.5, x)", "chapter": 4, "passes": {"image": "float f(float x) {\n    return step(0.5, x);   // the edge comes FIRST\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y * 1.4 + 0.5;\n    float px = 1.4 / iResolution.y;\n    vec3 col = vec3(0.07, 0.08, 0.1);\n    vec2 g = abs(fract(p * 10.0 + 0.5) - 0.5) / 10.0;\n    col += 0.06 * (1.0 - smoothstep(0.0, px, min(g.x, g.y)));\n    vec2 a = min(abs(p), abs(p - 1.0));\n    col += 0.25 * (1.0 - smoothstep(0.0, 1.5 * px, min(a.x, a.y)));\n    float y = f(p.x);\n    float slope = (f(p.x + px) - f(p.x - px)) / (2.0 * px);\n    float d = abs(p.y - y) / sqrt(1.0 + slope * slope);\n    col = mix(col, vec3(1.0, 0.65, 0.2), 1.0 - smoothstep(0.0, 2.0 * px, d));\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "plot-smoothstep", "label": "Example 4.5", "title": "f(x) = smoothstep(0.2, 0.8, x)", "chapter": 4, "passes": {"image": "float f(float x) {\n    return smoothstep(0.2, 0.8, x);   // try moving the edges closer together\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y * 1.4 + 0.5;\n    float px = 1.4 / iResolution.y;\n    vec3 col = vec3(0.07, 0.08, 0.1);\n    vec2 g = abs(fract(p * 10.0 + 0.5) - 0.5) / 10.0;\n    col += 0.06 * (1.0 - smoothstep(0.0, px, min(g.x, g.y)));\n    vec2 a = min(abs(p), abs(p - 1.0));\n    col += 0.25 * (1.0 - smoothstep(0.0, 1.5 * px, min(a.x, a.y)));\n    float y = f(p.x);\n    float slope = (f(p.x + px) - f(p.x - px)) / (2.0 * px);\n    float d = abs(p.y - y) / sqrt(1.0 + slope * slope);\n    col = mix(col, vec3(1.0, 0.65, 0.2), 1.0 - smoothstep(0.0, 2.0 * px, d));\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "edges", "label": "Example 4.6", "title": "Hard edge (top) versus smoothstep edge (bottom)", "chapter": 4, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n\n    float edge = 0.3 * uv.x;                 // a slanted boundary\n    float hard = step(edge, uv.y);           // 0 or 1, nothing in between\n    float soft = smoothstep(edge - 0.15, edge + 0.15, uv.y);   // a wide, soft ramp\n\n    float v = uv.y > 0.0 ? hard : soft;      // top half hard, bottom half soft\n    fragColor = vec4(vec3(v), 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "plot-abs", "label": "Example 4.7", "title": "f(x) = abs(x − 0.5) × 2: a V centered at 0.5", "chapter": 4, "passes": {"image": "float f(float x) {\n    return abs(x - 0.5) * 2.0;   // distance from 0.5, doubled. Try clamp(x, 0.2, 0.7) too.\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y * 1.4 + 0.5;\n    float px = 1.4 / iResolution.y;\n    vec3 col = vec3(0.07, 0.08, 0.1);\n    vec2 g = abs(fract(p * 10.0 + 0.5) - 0.5) / 10.0;\n    col += 0.06 * (1.0 - smoothstep(0.0, px, min(g.x, g.y)));\n    vec2 a = min(abs(p), abs(p - 1.0));\n    col += 0.25 * (1.0 - smoothstep(0.0, 1.5 * px, min(a.x, a.y)));\n    float y = f(p.x);\n    float slope = (f(p.x + px) - f(p.x - px)) / (2.0 * px);\n    float d = abs(p.y - y) / sqrt(1.0 + slope * slope);\n    col = mix(col, vec3(1.0, 0.65, 0.2), 1.0 - smoothstep(0.0, 2.0 * px, d));\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "plot-fract", "label": "Example 4.8", "title": "f(x) = fract(x × 3): a sawtooth that repeats 3 times per unit", "chapter": 4, "passes": {"image": "float f(float x) {\n    return fract(x * 3.0);   // try floor(x * 3.0) / 3.0, then mod(x, 0.4)\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y * 1.4 + 0.5;\n    float px = 1.4 / iResolution.y;\n    vec3 col = vec3(0.07, 0.08, 0.1);\n    vec2 g = abs(fract(p * 10.0 + 0.5) - 0.5) / 10.0;\n    col += 0.06 * (1.0 - smoothstep(0.0, px, min(g.x, g.y)));\n    vec2 a = min(abs(p), abs(p - 1.0));\n    col += 0.25 * (1.0 - smoothstep(0.0, 1.5 * px, min(a.x, a.y)));\n    float y = f(p.x);\n    float slope = (f(p.x + px) - f(p.x - px)) / (2.0 * px);\n    float d = abs(p.y - y) / sqrt(1.0 + slope * slope);\n    col = mix(col, vec3(1.0, 0.65, 0.2), 1.0 - smoothstep(0.0, 2.0 * px, d));\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "mix-colors", "label": "Example 4.9", "title": "mix between two colors, shaped by smoothstep", "chapter": 4, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.xy;\n\n    vec3 deep = vec3(0.05, 0.15, 0.45);    // night blue\n    vec3 warm = vec3(1.0, 0.55, 0.25);     // sunset orange\n\n    float t = uv.y;                                 // top half: a plain straight blend\n    if (uv.x > 0.5) t = smoothstep(0.3, 0.7, uv.y); // right half: shaped by smoothstep\n\n    fragColor = vec4(mix(warm, deep, t), 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "plot-bump", "label": "Example 4.10", "title": "A plateau built from two smoothsteps", "chapter": 4, "passes": {"image": "float f(float x) {\n    return smoothstep(0.2, 0.3, x) - smoothstep(0.6, 0.7, x);   // try exp(-x * 4.0) or 0.05 / x\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y * 1.4 + 0.5;\n    float px = 1.4 / iResolution.y;\n    vec3 col = vec3(0.07, 0.08, 0.1);\n    vec2 g = abs(fract(p * 10.0 + 0.5) - 0.5) / 10.0;\n    col += 0.06 * (1.0 - smoothstep(0.0, px, min(g.x, g.y)));\n    vec2 a = min(abs(p), abs(p - 1.0));\n    col += 0.25 * (1.0 - smoothstep(0.0, 1.5 * px, min(a.x, a.y)));\n    float y = f(p.x);\n    float slope = (f(p.x + px) - f(p.x - px)) / (2.0 * px);\n    float d = abs(p.y - y) / sqrt(1.0 + slope * slope);\n    col = mix(col, vec3(1.0, 0.65, 0.2), 1.0 - smoothstep(0.0, 2.0 * px, d));\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "paint", "label": "Example 4.11", "title": "One ramp, four shapes", "chapter": 4, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.xy;\n    float x = uv.x;\n\n    float v;\n    if (uv.y < 0.25)      v = x;                                  // straight\n    else if (uv.y < 0.5)  v = x * x * x;                          // slow start\n    else if (uv.y < 0.75) v = smoothstep(0.45, 0.55, x);          // nearly a switch\n    else                  v = step(0.5, fract(x * 8.0));          // eight stripes\n\n    vec3 col = mix(vec3(0.1, 0.12, 0.3), vec3(1.0, 0.75, 0.4), v);\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "wave-plot", "label": "Example 5.1", "title": "f(x) = sin(x), one full period and a bit", "chapter": 5, "passes": {"image": "float f(float x) {\n    return sin(x);   // try cos(x), sin(2.0 * x), 0.5 * sin(x)\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    // View: x from about -0.4 to 6.7 (just over one full turn), y from -2 to 2.\n    vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y * 4.0 + vec2(3.14159, 0.0);\n    float px = 4.0 / iResolution.y;\n\n    vec3 col = vec3(0.07, 0.08, 0.1);\n    float gx = abs(fract(p.x / 1.5708 + 0.5) - 0.5) * 1.5708;      // quarter turns\n    float gy = abs(fract(p.y * 2.0 + 0.5) - 0.5) / 2.0;            // every 0.5\n    col += 0.07 * (1.0 - smoothstep(0.0, px, min(gx, gy)));\n    float lines = min(abs(p.y), abs(abs(p.y) - 1.0));              // y = 0 and y = ±1\n    col += 0.2 * (1.0 - smoothstep(0.0, 1.5 * px, min(lines, abs(p.x))));\n\n    float y = f(p.x);\n    float slope = (f(p.x + px) - f(p.x - px)) / (2.0 * px);\n    float d = abs(p.y - y) / sqrt(1.0 + slope * slope);\n    col = mix(col, vec3(0.5, 0.85, 1.0), 1.0 - smoothstep(0.0, 2.0 * px, d));\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "wave-afp", "label": "Example 5.2", "title": "Amplitude, frequency and phase, each with its own number", "chapter": 5, "passes": {"image": "float f(float x) {\n    float amplitude = 0.8;   // click these numbers and drag\n    float frequency = 3.0;\n    float phase     = 0.0;\n    return amplitude * sin(frequency * x + phase);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y * 4.0 + vec2(3.14159, 0.0);\n    float px = 4.0 / iResolution.y;\n    vec3 col = vec3(0.07, 0.08, 0.1);\n    float gx = abs(fract(p.x / 1.5708 + 0.5) - 0.5) * 1.5708;\n    float gy = abs(fract(p.y * 2.0 + 0.5) - 0.5) / 2.0;\n    col += 0.07 * (1.0 - smoothstep(0.0, px, min(gx, gy)));\n    float lines = min(abs(p.y), abs(abs(p.y) - 1.0));\n    col += 0.2 * (1.0 - smoothstep(0.0, 1.5 * px, min(lines, abs(p.x))));\n    float y = f(p.x);\n    float slope = (f(p.x + px) - f(p.x - px)) / (2.0 * px);\n    float d = abs(p.y - y) / sqrt(1.0 + slope * slope);\n    col = mix(col, vec3(0.5, 0.85, 1.0), 1.0 - smoothstep(0.0, 2.0 * px, d));\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "pulse", "label": "Example 5.3", "title": "sin(iTime): the whole canvas breathes", "chapter": 5, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.xy;\n\n    float pulse = 0.5 + 0.5 * sin(iTime);   // 0 → 1 → 0 … one cycle every 2π ≈ 6.3 seconds\n\n    vec3 col = mix(vec3(0.1, 0.2, 0.5), vec3(1.0, 0.6, 0.2), pulse);\n    col *= 0.6 + 0.4 * uv.y;                // a little vertical shading so it isn't flat\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "travel", "label": "Example 5.4", "title": "sin(x × 20 − time × 3): stripes that move", "chapter": 5, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.xy;\n\n    float wave = 0.5 + 0.5 * sin(uv.x * 20.0 - iTime * 3.0);\n\n    fragColor = vec4(vec3(wave), 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "interference", "label": "Example 5.5", "title": "Three waves in different directions, added up", "chapter": 5, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    float t = iTime;\n\n    float v = 0.0;\n    v += sin(uv.x * 6.0 + t);                       // a wave along x\n    v += sin(uv.y * 5.0 - t * 1.3);                 // a wave along y\n    v += sin((uv.x + uv.y) * 4.0 + t * 0.7);        // a diagonal wave\n    v /= 3.0;                                       // the sum ranges -3..3, now -1..1\n\n    vec3 col = 0.5 + 0.5 * cos(v * 3.0 + vec3(0.0, 2.0, 4.0));   // a color for each value\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "shadertoy-new", "label": "Example 5.6", "title": "Shadertoy's default shader, which you can now read", "chapter": 5, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    // Normalized pixel coordinates (from 0 to 1)\n    vec2 uv = fragCoord / iResolution.xy;\n\n    // Time varying pixel color\n    vec3 col = 0.5 + 0.5 * cos(iTime + uv.xyx + vec3(0, 2, 4));\n\n    // Output to screen\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "wave-shapes", "label": "Example 5.7", "title": "Four waves, moving: sine, saw, triangle, square", "chapter": 5, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.xy;\n    float x = uv.x * 4.0 - iTime * 0.5;        // four cycles across, sliding\n\n    float v;\n    if (uv.y > 0.75)      v = 0.5 + 0.5 * sin(x * 6.28318);   // sine\n    else if (uv.y > 0.5)  v = fract(x);                      // sawtooth\n    else if (uv.y > 0.25) v = abs(fract(x) - 0.5) * 2.0;     // triangle\n    else                  v = step(0.5, fract(x));           // square\n\n    fragColor = vec4(v, v * 0.7, 0.3, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "light-add", "label": "Example 6.1", "title": "Three spotlights: light adds up", "chapter": 6, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n\n    // three disc-shaped lights, each 1.0 inside and 0.0 outside (soft edges)\n    float r = 1.0 - smoothstep(0.55, 0.57, length(uv - vec2(-0.3, 0.2)));\n    float g = 1.0 - smoothstep(0.55, 0.57, length(uv - vec2( 0.3, 0.2)));\n    float b = 1.0 - smoothstep(0.55, 0.57, length(uv - vec2( 0.0, -0.3)));\n\n    vec3 col = vec3(0.0);\n    col += vec3(1.0, 0.0, 0.0) * r;   // red light\n    col += vec3(0.0, 1.0, 0.0) * g;   // green light\n    col += vec3(0.0, 0.0, 1.0) * b;   // blue light\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "rgb-cube", "label": "Example 6.2", "title": "A moving slice through the RGB cube", "chapter": 6, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.xy;\n    float blue = 0.5 + 0.5 * sin(iTime);       // the slice slides through the cube\n\n    fragColor = vec4(uv.x, uv.y, blue, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "luminance", "label": "Example 6.3", "title": "Pure red, green and blue, and how bright they really look", "chapter": 6, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.xy;\n\n    vec3 col = vec3(1.0, 0.0, 0.0);                  // left third: red\n    if (uv.x > 0.333) col = vec3(0.0, 1.0, 0.0);     // middle: green\n    if (uv.x > 0.666) col = vec3(0.0, 0.0, 1.0);     // right: blue\n\n    float lum = dot(col, vec3(0.299, 0.587, 0.114)); // perceived brightness\n    if (uv.y < 0.5) col = vec3(lum);                 // bottom half: shown as grey\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "gradient-stops", "label": "Example 6.4", "title": "A three-stop gradient: horizon, sky, space", "chapter": 6, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.xy;\n    float y = uv.y;\n\n    vec3 horizon = vec3(1.0, 0.55, 0.3);\n    vec3 sky     = vec3(0.35, 0.45, 0.85);\n    vec3 space   = vec3(0.03, 0.03, 0.12);\n\n    vec3 col = mix(horizon, sky, smoothstep(0.0, 0.45, y));   // first blend, low down\n    col = mix(col, space, smoothstep(0.5, 1.0, y));           // second blend, higher up\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "hsv", "label": "Example 6.5", "title": "HSV: hue across, saturation up", "chapter": 6, "passes": {"image": "// Hue, saturation, value (each 0..1) to red, green, blue.\nvec3 hsv2rgb(vec3 c) {\n    vec3 rgb = clamp(abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);\n    return c.z * mix(vec3(1.0), rgb, c.y);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.xy;\n\n    float hue = uv.x;          // all the way around the color wheel\n    float sat = uv.y;          // washed out at the bottom, vivid at the top\n    float val = 1.0;\n\n    fragColor = vec4(hsv2rgb(vec3(hue, sat, val)), 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "palette-plot", "label": "Example 6.6", "title": "A palette is three waves out of step", "chapter": 6, "passes": {"image": "// Inigo Quilez's cosine palette: a number goes in, a color comes out.\nvec3 palette(float t) {\n    vec3 a = vec3(0.5, 0.5, 0.5);\n    vec3 b = vec3(0.5, 0.5, 0.5);\n    vec3 c = vec3(1.0, 1.0, 1.0);\n    vec3 d = vec3(0.00, 0.33, 0.67);   // try (0.0, 0.10, 0.20) or (0.30, 0.20, 0.20)\n    return a + b * cos(6.28318 * (c * t + d));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.xy;\n    vec3 pal = palette(uv.x);\n\n    vec3 col = pal;                          // top half: the palette\n    if (uv.y < 0.5) {                        // bottom half: its three waves\n        float y = uv.y * 2.0;\n        float w = 3.0 / iResolution.y;\n        col = vec3(0.07);\n        col += vec3(1.0, 0.25, 0.25) * (1.0 - smoothstep(0.0, w, abs(y - pal.r)));\n        col += vec3(0.25, 1.0, 0.35) * (1.0 - smoothstep(0.0, w, abs(y - pal.g)));\n        col += vec3(0.35, 0.5, 1.0)  * (1.0 - smoothstep(0.0, w, abs(y - pal.b)));\n    }\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "palette-use", "label": "Example 6.7", "title": "A palette fed with distance and time", "chapter": 6, "passes": {"image": "vec3 palette(float t) {\n    vec3 a = vec3(0.5, 0.5, 0.5);\n    vec3 b = vec3(0.5, 0.5, 0.5);\n    vec3 c = vec3(1.0, 1.0, 0.5);\n    vec3 d = vec3(0.80, 0.90, 0.30);\n    return a + b * cos(6.28318 * (c * t + d));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    float r = length(uv);                              // distance from the center\n\n    vec3 col = palette(r * 0.8 - iTime * 0.2);         // color depends on distance and time\n    col *= 0.75 + 0.25 * sin(r * 40.0);                // fine ridges, for texture\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "gamma", "label": "Example 6.8", "title": "Red to green: mixed as screen values (top) and as light (bottom)", "chapter": 6, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.xy;\n    vec3 red = vec3(1.0, 0.0, 0.0), green = vec3(0.0, 1.0, 0.0);\n\n    vec3 col;\n    if (uv.y > 0.5) {\n        col = mix(red, green, uv.x);                       // naive: mix the screen values\n    } else {\n        vec3 lin = mix(pow(red, vec3(2.2)), pow(green, vec3(2.2)), uv.x);   // mix as light\n        col = pow(lin, vec3(1.0 / 2.2));                   // then convert for the screen\n    }\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "tonemap", "label": "Example 6.9", "title": "Glow clipped (left) and tone mapped (right)", "chapter": 6, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n\n    // a bright glow: very large near the center\n    vec3 light = vec3(1.0, 0.5, 0.2) * 0.3 / length(uv - vec2(0.0, 0.0));\n\n    vec3 col = light;                            // left: values above 1 are simply clipped\n    if (uv.x > 0.0) col = 1.0 - exp(-light);     // right: tone mapped, highlights keep shape\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "offset", "label": "Example 7.1", "title": "uv − c: every pixel measured from a moving point", "chapter": 7, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n\n    vec2 c = vec2(0.7 * cos(iTime * 0.7), 0.4 * sin(iTime));   // a point that wanders\n    vec2 q = uv - c;                                           // arrow from c to this pixel\n\n    vec3 col = vec3(0.08, 0.09, 0.12);\n    // grid lines every 0.25 units of q, so the grid is centered on c\n    vec2 cell = abs(fract(q * 4.0 + 0.5) - 0.5);               // 0 on a grid line\n    col += 0.18 * step(min(cell.x, cell.y), 0.03);\n    // q's own axes: where q.x = 0 and where q.y = 0\n    col = mix(col, vec3(1.0, 0.6, 0.2), step(abs(q.x), 0.006));\n    col = mix(col, vec3(0.4, 0.7, 1.0), step(abs(q.y), 0.006));\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "closer", "label": "Example 7.2", "title": "Which point is closer? Two distances, compared", "chapter": 7, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n\n    vec2 a = vec2(-0.6, 0.0) + 0.3 * vec2(cos(iTime), sin(iTime * 1.3));\n    vec2 b = vec2( 0.6, 0.1) + 0.3 * vec2(sin(iTime * 0.8), cos(iTime));\n\n    float da = distance(uv, a);              // the same as length(uv - a)\n    float db = distance(uv, b);\n    float d  = min(da, db);                  // distance to whichever is nearer\n\n    vec3 col = da < db ? vec3(0.25, 0.45, 0.9) : vec3(1.0, 0.55, 0.2);\n    col *= 0.8 + 0.2 * cos(d * 60.0);        // rings of equal distance\n    col = mix(col, vec3(1.0), step(d, 0.03)); // the two points themselves\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "metrics", "label": "Example 7.3", "title": "Three ways to measure distance, three kinds of circle", "chapter": 7, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    // split the canvas into three panels, each with its own centered coordinates\n    float panelW = iResolution.x / 3.0;\n    float panel = floor(fragCoord.x / panelW);                 // 0, 1 or 2\n    vec2 local = vec2(fragCoord.x - panel * panelW, fragCoord.y);\n    vec2 p = (local * 2.0 - vec2(panelW, iResolution.y)) / iResolution.y;\n\n    float d;\n    if (panel == 0.0)      d = length(p);                      // straight line (Pythagoras)\n    else if (panel == 1.0) d = abs(p.x) + abs(p.y);            // taxicab: along the grid\n    else                   d = max(abs(p.x), abs(p.y));        // the bigger part\n\n    vec3 col = mix(vec3(0.1, 0.11, 0.15), vec3(1.0, 0.6, 0.2), step(d, 0.6));\n    col *= 0.8 + 0.2 * cos(d * 40.0 - iTime * 3.0);            // rings of equal distance\n    if (local.x < 1.5) col = vec3(0.35);                       // panel borders\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "directions", "label": "Example 7.4", "title": "normalize: only the direction survives", "chapter": 7, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n\n    vec2 dir = normalize(uv);                  // length 1, pointing from the center to the pixel\n    vec3 col = vec3(dir * 0.5 + 0.5, 0.6);     // its x and y (-1..1) shown as red and green\n\n    // for comparison, the bottom strip shows uv itself, length included\n    if (uv.y < -0.75) col = vec3(uv * 0.5 + 0.5, 0.6);\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "dot-ramp", "label": "Example 7.5", "title": "dot(uv, dir): a gradient pointing any way you like", "chapter": 7, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n\n    float angle = iTime * 0.4;\n    vec2 dir = vec2(cos(angle), sin(angle));          // a unit arrow, slowly turning\n\n    float along = dot(uv, dir);                        // how far along dir this pixel is\n\n    vec3 col = mix(vec3(0.15, 0.25, 0.6), vec3(1.0, 0.6, 0.2), along * 0.5 + 0.5);\n    col *= 0.8 + 0.2 * sin(along * 30.0);              // stripes at right angles to dir\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "line-side", "label": "Example 7.6", "title": "dot with a normal: which side, and how far", "chapter": 7, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n\n    vec2 p = vec2(0.2, 0.0);                               // a point on the line\n    vec2 n = vec2(cos(iTime * 0.5), sin(iTime * 0.5));     // the line's normal (unit length)\n\n    float s = dot(uv - p, n);                              // signed distance to the line\n\n    vec3 col = s > 0.0 ? vec3(1.0, 0.55, 0.2) : vec3(0.25, 0.45, 0.9);   // which side\n    col *= 0.75 + 0.25 * cos(s * 50.0);                    // contours every 0.126\n    col = mix(col, vec3(1.0), step(abs(s), 0.01));         // the line itself: |s| small\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "ball", "label": "Example 7.7", "title": "Lambert lighting: brightness = dot(normal, light)", "chapter": 7, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    vec2 p = uv / 0.8;                                 // a ball of radius 0.8 on screen\n\n    vec3 col = vec3(0.01, 0.012, 0.02);                // background (dark: gamma brightens it)\n    float r2 = dot(p, p);                              // squared distance from the center\n    if (r2 < 1.0) {\n        float z = sqrt(1.0 - r2);                      // how far the surface sticks out\n        vec3 normal = vec3(p, z);                      // on a ball, the point is its own normal\n\n        vec3 light = normalize(vec3(cos(iTime), 0.6, sin(iTime) + 0.4));   // the light circles round\n        float diffuse = max(dot(normal, light), 0.0);  // facing away (negative) counts as 0\n\n        col = vec3(1.0, 0.6, 0.25) * (0.06 + diffuse); // a little ambient light plus diffuse\n    }\n    fragColor = vec4(pow(col, vec3(1.0 / 2.2)), 1.0);  // gamma, from Chapter 6\n}", "buffer": null}, "cfg": {}}, {"id": "aa", "label": "Example 8.1", "title": "Magnified pixels: yes/no edge (left), coverage from distance (right)", "chapter": 8, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    float B = 10.0;                                       // big-pixel size, in real pixels\n    vec2 center = floor(fragCoord / B) * B + B * 0.5;     // the center of this big pixel\n    vec2 uv = (center * 2.0 - iResolution.xy) / iResolution.y;\n    float px = 2.0 * B / iResolution.y;                   // one big pixel, in uv units\n\n    vec2 c = vec2(uv.x < 0.0 ? -0.85 : 0.85, 0.0);        // one circle in each half\n    float d = length(uv - c) - 0.6;                       // how far outside the edge (negative = inside)\n\n    float fill;\n    if (uv.x < 0.0) fill = d < 0.0 ? 1.0 : 0.0;           // left: inside or not\n    else            fill = clamp(0.5 - d / px, 0.0, 1.0); // right: the covered fraction\n\n    vec3 col = mix(vec3(0.08, 0.09, 0.12), vec3(1.0, 0.6, 0.2), fill);\n    vec2 g = mod(fragCoord, B);\n    if (min(g.x, g.y) < 1.0) col *= 0.7;                  // thin lines between big pixels\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "field", "label": "Example 8.2", "title": "The distance field of a circle", "chapter": 8, "passes": {"image": "// Color a signed distance: orange outside, blue inside, a band every 0.05, white edge.\nvec3 field(float d, float px) {\n    vec3 col = d > 0.0 ? vec3(0.95, 0.6, 0.3) : vec3(0.4, 0.65, 1.0);\n    col *= 1.0 - exp(-4.0 * abs(d));             // darker close to the edge\n    col *= 0.8 + 0.2 * cos(125.66 * d);          // bands: cos repeats every 0.05\n    return mix(col, vec3(1.0), 1.0 - smoothstep(0.0, 1.5 * px, abs(d)));   // the edge\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    float px = 2.0 / iResolution.y;\n\n    float d = length(uv) - 0.5;                  // a circle of radius 0.5\n    fragColor = vec4(field(d, px), 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "effects", "label": "Example 8.3", "title": "One distance, four looks: fill, outline, glow, ripples", "chapter": 8, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    // split into 2 x 2 panels, each with its own centered coordinates\n    vec2 size = iResolution.xy * 0.5;\n    vec2 cell = floor(fragCoord / size);               // (0,0) bottom-left .. (1,1) top-right\n    vec2 local = fragCoord - cell * size;\n    vec2 p = (local * 2.0 - size) / size.y;\n    float px = 2.0 / size.y;\n\n    float d = length(p) - 0.55;                        // the circle's signed distance\n    vec3 amber = vec3(1.0, 0.6, 0.2);\n    vec3 col = vec3(0.07, 0.08, 0.1);\n\n    if (cell == vec2(0.0, 1.0))                        // top-left: filled, smooth edge\n        col = mix(col, amber, 1.0 - smoothstep(-px, px, d));\n    if (cell == vec2(1.0, 1.0))                        // top-right: outline, |d| < thickness\n        col = mix(col, amber, 1.0 - smoothstep(-px, px, abs(d) - 0.03));\n    if (cell == vec2(0.0, 0.0))                        // bottom-left: glow, bright near d = 0\n        col += amber * 0.02 / max(abs(d), 0.002);\n    if (cell == vec2(1.0, 0.0)) {                      // bottom-right: ripples moving outward\n        float r = abs(fract(d * 6.0 - iTime) - 0.5) / 6.0;   // distance to the nearest ripple\n        col = mix(col, amber, (1.0 - smoothstep(-px, px, r - 0.012)) * exp(-2.0 * max(d, 0.0)));\n    }\n    if (min(local.x, local.y) < 1.5) col = vec3(0.3);  // panel borders\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "box", "label": "Example 8.4", "title": "A rounded box, and a probe circle that just touches it", "chapter": 8, "passes": {"image": "float sdBox(vec2 p, vec2 b) {\n    vec2 q = abs(p) - b;\n    return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0);\n}\n\nvec3 field(float d, float px) {\n    vec3 col = d > 0.0 ? vec3(0.95, 0.6, 0.3) : vec3(0.4, 0.65, 1.0);\n    col *= 1.0 - exp(-4.0 * abs(d));\n    col *= 0.8 + 0.2 * cos(125.66 * d);\n    return mix(col, vec3(1.0), 1.0 - smoothstep(0.0, 1.5 * px, abs(d)));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    float px = 2.0 / iResolution.y;\n\n    float r = 0.15 + 0.15 * sin(iTime);              // corner rounding, 0 .. 0.3\n    vec2 halfSize = vec2(0.7, 0.4);\n    float d = sdBox(uv, halfSize - r) - r;           // shrink, then grow back rounded\n    vec3 col = field(d, px);\n\n    // the probe: a circle around the pointer whose radius is the distance there\n    vec2 m = (iMouse.xy * 2.0 - iResolution.xy) / iResolution.y;\n    if (iMouse.xy == vec2(0.0)) m = vec2(1.05 * cos(iTime * 0.4), 0.75 * sin(iTime * 0.6));\n    float dm = sdBox(m, halfSize - r) - r;\n    col = mix(col, vec3(1.0), 1.0 - smoothstep(0.0, 1.5 * px, abs(length(uv - m) - abs(dm))));\n    col = mix(col, vec3(1.0), 1.0 - smoothstep(0.0, px, length(uv - m) - 0.02));\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "clock", "label": "Example 8.5", "title": "A clock made of segments, set to your computer's time", "chapter": 8, "passes": {"image": "float sdSegment(vec2 p, vec2 a, vec2 b) {\n    vec2 pa = p - a, ba = b - a;\n    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);\n    return length(pa - ba * h);\n}\n\n// The direction of a clock hand: 'turns' is 0..1 clockwise from 12 o'clock.\nvec2 hand(float turns) {\n    float a = 1.5708 - turns * 6.28318;      // start at the top, go clockwise\n    return vec2(cos(a), sin(a));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    float px = 2.0 / iResolution.y;\n\n    float secs = iDate.w;                    // seconds since midnight\n    float s = fract(secs / 60.0);            // each hand: how far round its dial, 0..1\n    float m = fract(secs / 3600.0);\n    float h = fract(secs / 43200.0);         // 12 hours = 43200 seconds per turn\n\n    vec3 col = vec3(0.08, 0.09, 0.12);\n    float face = length(uv) - 0.85;\n    col = mix(col, vec3(0.95, 0.93, 0.88), 1.0 - smoothstep(-px, px, face));\n\n    for (int i = 0; i < 12; i++) {           // twelve tick marks\n        vec2 dir = hand(float(i) / 12.0);\n        float t = sdSegment(uv, dir * 0.7, dir * 0.78) - 0.012;\n        col = mix(col, vec3(0.2), 1.0 - smoothstep(-px, px, t));\n    }\n    float hands = min(sdSegment(uv, vec2(0.0), hand(h) * 0.42) - 0.03,\n                      sdSegment(uv, vec2(0.0), hand(m) * 0.62) - 0.02);\n    col = mix(col, vec3(0.15), 1.0 - smoothstep(-px, px, hands));\n    float sec = sdSegment(uv, -hand(s) * 0.12, hand(s) * 0.7) - 0.006;\n    col = mix(col, vec3(0.9, 0.3, 0.2), 1.0 - smoothstep(-px, px, sec));\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "combine", "label": "Example 8.6", "title": "Union, intersection, subtraction of a box and a circle", "chapter": 8, "passes": {"image": "float sdBox(vec2 p, vec2 b) {\n    vec2 q = abs(p) - b;\n    return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0);\n}\n\nvec3 field(float d, float px) {\n    vec3 col = d > 0.0 ? vec3(0.95, 0.6, 0.3) : vec3(0.4, 0.65, 1.0);\n    col *= 1.0 - exp(-4.0 * abs(d));\n    col *= 0.8 + 0.2 * cos(125.66 * d);\n    return mix(col, vec3(1.0), 1.0 - smoothstep(0.0, 1.5 * px, abs(d)));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    float panelW = iResolution.x / 3.0;\n    float panel = floor(fragCoord.x / panelW);                  // 0, 1, 2\n    vec2 local = vec2(fragCoord.x - panel * panelW, fragCoord.y);\n    vec2 p = (local * 2.0 - vec2(panelW, iResolution.y)) / iResolution.y;\n    float px = 2.0 / iResolution.y;\n\n    float d1 = sdBox(p, vec2(0.35, 0.35));                      // shape 1: a box\n    float d2 = length(p - vec2(0.3 * sin(iTime), 0.3)) - 0.3;   // shape 2: a moving circle\n\n    float d;\n    if (panel == 0.0)      d = min(d1, d2);                     // union\n    else if (panel == 1.0) d = max(d1, d2);                     // intersection\n    else                   d = max(d1, -d2);                    // box minus circle\n\n    vec3 col = field(d, px);\n    if (local.x < 1.5) col = vec3(0.3);\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "blobs", "label": "Example 8.7", "title": "Metaballs: six circles joined with smin", "chapter": 8, "passes": {"image": "float smin(float a, float b, float k) {\n    float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);\n    return mix(b, a, h) - k * h * (1.0 - h);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    float px = 2.0 / iResolution.y;\n\n    float d = 100.0;                                   // start far away from everything\n    for (int i = 0; i < 6; i++) {\n        float fi = float(i);\n        vec2 c = vec2(0.9 * cos(iTime * (0.3 + 0.07 * fi) + fi * 2.1),\n                      0.5 * sin(iTime * (0.4 + 0.05 * fi) + fi * 1.3));\n        d = smin(d, length(uv - c) - (0.16 + 0.025 * fi), 0.25);   // try k = 0.0 or 0.5\n    }\n\n    vec3 col = vec3(0.04, 0.04, 0.07);\n    col += vec3(1.0, 0.45, 0.2) * 0.01 / max(abs(d), 0.003);         // glow around the edge\n    vec3 inside = mix(vec3(1.0, 0.8, 0.35), vec3(0.85, 0.2, 0.4), clamp(-d * 5.0, 0.0, 1.0));\n    col = mix(col, inside, 1.0 - smoothstep(-px, px, d));\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "move-scale", "label": "Example 9.1", "title": "Moving and scaling a box by transforming the coordinates", "chapter": 9, "passes": {"image": "float sdBox(vec2 p, vec2 b) {\n    vec2 q = abs(p) - b;\n    return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0);\n}\n\nvec3 field(float d, float px) {\n    vec3 col = d > 0.0 ? vec3(0.95, 0.6, 0.3) : vec3(0.4, 0.65, 1.0);\n    col *= 1.0 - exp(-4.0 * abs(d));\n    col *= 0.8 + 0.2 * cos(125.66 * d);\n    return mix(col, vec3(1.0), 1.0 - smoothstep(0.0, 1.5 * px, abs(d)));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    float px = 2.0 / iResolution.y;\n\n    vec2 pos = vec2(0.6 * sin(iTime * 0.7), 0.0);    // where the box should be\n    float s = 1.0 + 0.5 * sin(iTime);                // how big: 0.5 to 1.5 times\n\n    vec2 q = (uv - pos) / s;                         // move, then scale, the coordinates\n    float d = sdBox(q, vec2(0.3, 0.2)) * s;          // * s: back to real distance\n\n    fragColor = vec4(field(d, px), 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "rotate-box", "label": "Example 9.2", "title": "A turning box: rotate the coordinates the other way", "chapter": 9, "passes": {"image": "vec2 rotate(vec2 p, float a) {\n    float c = cos(a), s = sin(a);\n    return vec2(c * p.x - s * p.y, s * p.x + c * p.y);\n}\n\nfloat sdBox(vec2 p, vec2 b) {\n    vec2 q = abs(p) - b;\n    return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0);\n}\n\nvec3 field(float d, float px) {\n    vec3 col = d > 0.0 ? vec3(0.95, 0.6, 0.3) : vec3(0.4, 0.65, 1.0);\n    col *= 1.0 - exp(-4.0 * abs(d));\n    col *= 0.8 + 0.2 * cos(125.66 * d);\n    return mix(col, vec3(1.0), 1.0 - smoothstep(0.0, 1.5 * px, abs(d)));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    float px = 2.0 / iResolution.y;\n\n    float angle = iTime * 0.5;                       // the shape turns counterclockwise\n    vec2 q = rotate(uv, -angle);                     // so the coordinates turn clockwise\n    float d = sdBox(q, vec2(0.6, 0.2));\n\n    fragColor = vec4(field(d, px), 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "order", "label": "Example 9.3", "title": "Move then turn (left) versus turn then move (right)", "chapter": 9, "passes": {"image": "vec2 rotate(vec2 p, float a) {\n    float c = cos(a), s = sin(a);\n    return vec2(c * p.x - s * p.y, s * p.x + c * p.y);\n}\n\nfloat sdBox(vec2 p, vec2 b) {\n    vec2 q = abs(p) - b;\n    return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    float panelW = iResolution.x / 2.0;                        // two panels side by side\n    float panel = floor(fragCoord.x / panelW);\n    vec2 local = vec2(fragCoord.x - panel * panelW, fragCoord.y);\n    vec2 p = (local * 2.0 - vec2(panelW, iResolution.y)) / iResolution.y;\n    float px = 2.0 / iResolution.y;\n\n    vec2 offset = vec2(0.5, 0.0);\n    vec2 q;\n    if (panel == 0.0) q = rotate(p - offset, -iTime);          // move to offset, then turn there\n    else              q = rotate(p, -iTime) - offset;          // turn around the center, then move\n\n    vec3 col = vec3(0.08, 0.09, 0.12);\n    col += 0.1 * (1.0 - smoothstep(0.0, 1.5 * px, abs(length(p) - 0.5)));   // a guide circle\n    float d = sdBox(q, vec2(0.2, 0.08));\n    col = mix(col, vec3(1.0, 0.6, 0.2), 1.0 - smoothstep(-px, px, d));\n    col = mix(col, vec3(1.0), 1.0 - smoothstep(-px, px, length(p) - 0.025));  // the center\n    if (local.x < 1.5) col = vec3(0.3);\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "pendulum", "label": "Example 9.4", "title": "A pendulum: draw it hanging still, swing the space", "chapter": 9, "passes": {"image": "vec2 rotate(vec2 p, float a) {\n    float c = cos(a), s = sin(a);\n    return vec2(c * p.x - s * p.y, s * p.x + c * p.y);\n}\n\nfloat sdSegment(vec2 p, vec2 a, vec2 b) {\n    vec2 pa = p - a, ba = b - a;\n    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);\n    return length(pa - ba * h);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    float px = 2.0 / iResolution.y;\n\n    vec2 pivot = vec2(0.0, 0.85);\n    float angle = 0.7 * sin(iTime * 2.0);              // swing back and forth (radians)\n    vec2 q = rotate(uv - pivot, -angle);               // the pendulum's own coordinates\n\n    // In its own coordinates the pendulum hangs straight down from (0, 0).\n    float rod = sdSegment(q, vec2(0.0), vec2(0.0, -1.2)) - 0.012;\n    float bob = length(q - vec2(0.0, -1.2)) - 0.14;\n\n    vec3 col = vec3(0.08, 0.09, 0.12) + 0.04 * uv.y;\n    col = mix(col, vec3(0.6), 1.0 - smoothstep(-px, px, rod));\n    col = mix(col, vec3(1.0, 0.6, 0.2), 1.0 - smoothstep(-px, px, bob));\n    col = mix(col, vec3(0.9), 1.0 - smoothstep(-px, px, length(uv - pivot) - 0.03));\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "solar", "label": "Example 9.5", "title": "A sun, a planet and its moon, lit from the center", "chapter": 9, "passes": {"image": "vec2 rotate(vec2 p, float a) {\n    float c = cos(a), s = sin(a);\n    return vec2(c * p.x - s * p.y, s * p.x + c * p.y);\n}\n\n// A ball centered at c with radius r, lit by the sun at the origin.\n// Returns the color in .rgb and how much of this pixel it covers in .a\nvec4 ball(vec2 p, vec2 c, float r, vec3 albedo, float px) {\n    vec2 q = (p - c) / r;                              // -1..1 across the ball\n    float z = sqrt(max(1.0 - dot(q, q), 0.0));         // Chapter 7's ball\n    vec3 normal = vec3(q, z);\n    vec3 toSun = normalize(vec3(-c, 0.25));            // from the ball toward the origin\n    float light = max(dot(normal, toSun), 0.0);\n    float cover = 1.0 - smoothstep(-px, px, length(p - c) - r);\n    return vec4(albedo * (0.02 + light), cover);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    float px = 2.0 / iResolution.y;\n\n    vec2 planet = rotate(vec2(0.62, 0.0), iTime * 0.4);           // circles the sun\n    vec2 moon   = planet + rotate(vec2(0.2, 0.0), iTime * 1.7);   // circles the planet\n\n    vec3 col = vec3(0.003, 0.003, 0.008);\n    col += 0.006 * (1.0 - smoothstep(0.0, 1.5 * px, abs(length(uv) - 0.62)));          // orbits\n    col += 0.004 * (1.0 - smoothstep(0.0, 1.5 * px, abs(length(uv - planet) - 0.2)));\n\n    float sun = length(uv) - 0.15;\n    col += vec3(1.0, 0.5, 0.15) * 0.008 / max(sun, 0.004);                             // glow\n    col = mix(col, vec3(1.0, 0.75, 0.4) * 2.0, 1.0 - smoothstep(-px, px, sun));\n\n    vec4 p = ball(uv, planet, 0.09, vec3(0.25, 0.5, 1.0), px);\n    col = mix(col, p.rgb, p.a);\n    vec4 m = ball(uv, moon, 0.035, vec3(0.7), px);\n    col = mix(col, m.rgb, m.a);\n\n    col = 1.0 - exp(-col);                         // tone map (Chapter 6)\n    fragColor = vec4(pow(col, vec3(1.0 / 2.2)), 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "camera2d", "label": "Example 9.6", "title": "A camera is one transform from screen to world", "chapter": 9, "passes": {"image": "vec2 rotate(vec2 p, float a) {\n    float c = cos(a), s = sin(a);\n    return vec2(c * p.x - s * p.y, s * p.x + c * p.y);\n}\n\nfloat sdBox(vec2 p, vec2 b) {\n    vec2 q = abs(p) - b;\n    return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0);\n}\n\n// The world, drawn in world units. It knows nothing about the camera.\nvec3 world(vec2 p, float px) {\n    vec3 col = vec3(0.08, 0.09, 0.12);\n    vec2 g = abs(fract(p + 0.5) - 0.5);                // distance to the nearest grid line\n    col += 0.12 * (1.0 - smoothstep(0.0, px, min(g.x, g.y)));\n    float d = length(p - vec2(1.0, 0.5)) - 0.4;\n    d = min(d, sdBox(p - vec2(-1.2, -0.3), vec2(0.5, 0.3)));\n    d = min(d, length(p - vec2(0.2, -1.4)) - 0.25);\n    return mix(col, vec3(1.0, 0.6, 0.2), 1.0 - smoothstep(-px, px, d));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n\n    vec2  camPos   = 0.8 * vec2(sin(iTime * 0.3), cos(iTime * 0.23));  // where it looks\n    float viewSize = 2.0 + sin(iTime * 0.5);                           // world units per half-height\n    float camTurn  = iTime * 0.1;                                      // how far it has turned\n\n    vec2 p = rotate(uv * viewSize, camTurn) + camPos;   // screen -> world: scale, turn, move\n    float px = 2.0 * viewSize / iResolution.y;          // one pixel, in world units\n\n    fragColor = vec4(world(p, px), 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "tiles", "label": "Example 10.1", "title": "fract: every tile asks the same question", "chapter": 10, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    float n = 4.0;                          // tiles per unit\n    float px = 2.0 * n / iResolution.y;     // one pixel, in tile units\n\n    vec2 p = uv * n;                        // now one tile is one unit\n    vec2 local = fract(p) - 0.5;            // this pixel's position inside its tile, -0.5..0.5\n    float d = length(local) - 0.3;          // one circle, centered in the tile\n\n    vec3 col = mix(vec3(0.08, 0.09, 0.12), vec3(1.0, 0.6, 0.2), 1.0 - smoothstep(-px, px, d));\n    vec2 edge = 0.5 - abs(local);           // distance to the tile's border\n    col += 0.15 * (1.0 - smoothstep(0.0, px, min(edge.x, edge.y)));   // draw the borders\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "tile-ids", "label": "Example 10.2", "title": "floor gives each tile an id, and the id makes tiles differ", "chapter": 10, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    float n = 5.0;\n    float px = 2.0 * n / iResolution.y;\n\n    vec2 p = uv * n;\n    vec2 id = floor(p);                              // which tile: whole numbers\n    vec2 local = fract(p) - 0.5;                     // where in the tile\n\n    float checker = mod(id.x + id.y, 2.0);           // 0, 1, 0, 1... like a chessboard\n    vec3 col = mix(vec3(0.09, 0.1, 0.14), vec3(0.14, 0.15, 0.2), checker);\n\n    float phase = id.x * 0.7 + id.y * 1.3;           // a different number for every tile\n    float r = 0.25 + 0.15 * sin(iTime * 2.0 + phase);\n    vec3 ink = 0.5 + 0.5 * cos(6.28318 * (id.x * 0.08 + id.y * 0.05 + vec3(0.0, 0.33, 0.67)));\n    col = mix(col, ink, 1.0 - smoothstep(-px, px, length(local) - r));\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "bricks", "label": "Example 10.3", "title": "Bricks: offset every other row by half a brick", "chapter": 10, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.y;\n    vec2 brick = vec2(0.24, 0.1);                    // brick size, in uv units\n\n    vec2 p = uv / brick;                             // one brick = one unit\n    p.x += 0.5 * mod(floor(p.y), 2.0);               // odd rows slide half a brick\n    vec2 id = floor(p);\n    vec2 local = fract(p);\n\n    vec2 e = min(local, 1.0 - local) * brick;        // distance to this brick's edges, in uv units\n    float mortar = min(e.x, e.y);\n\n    float shade = 0.8 + 0.2 * sin(id.x * 3.7 + id.y * 5.3);   // vary each brick a little\n    vec3 col = vec3(0.7, 0.3, 0.2) * shade;\n    col = mix(vec3(0.85, 0.82, 0.75), col, smoothstep(0.004, 0.006, mortar));\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "mirror", "label": "Example 10.4", "title": "One fold: blobs that only exist on the right, mirrored", "chapter": 10, "passes": {"image": "float smin(float a, float b, float k) {\n    float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);\n    return mix(b, a, h) - k * h * (1.0 - h);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    float px = 2.0 / iResolution.y;\n\n    vec2 p = uv;\n    p.x = abs(p.x);                     // the fold: comment this out to see the unmirrored blobs\n\n    float d = 100.0;\n    for (int i = 0; i < 5; i++) {       // five blobs wandering around the right-hand side\n        float fi = float(i);\n        vec2 c = vec2(0.15 + 0.6 * (0.5 + 0.5 * sin(iTime * 0.6 + fi * 2.0)),\n                      0.6 * sin(iTime * 0.45 + fi * 1.7));\n        d = smin(d, length(p - c) - 0.1, 0.25);\n    }\n\n    vec3 col = vec3(0.05, 0.05, 0.08);\n    col += vec3(0.4, 0.5, 1.0) * 0.008 / max(abs(d), 0.003);\n    col = mix(col, vec3(0.95, 0.9, 1.0), 1.0 - smoothstep(-px, px, d));\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "polar-grid", "label": "Example 10.5", "title": "A grid drawn in polar coordinates: rings and rays", "chapter": 10, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    float px = 2.0 / iResolution.y;\n\n    float r = length(uv);                     // distance from the center\n    float a = atan(uv.y, uv.x);               // angle, -π..π\n\n    // grid coordinates: 12 slices around, 5 rings per unit of radius\n    vec2 g = vec2(a / 6.28318 * 12.0, r * 5.0);\n    vec2 toLine = abs(fract(g + 0.5) - 0.5);  // distance to the nearest grid line, in grid units\n    // one pixel in grid units: around the circle a pixel covers px / r radians\n    vec2 pxg = vec2(px / r / 6.28318 * 12.0, px * 5.0);\n    float lines = 1.0 - smoothstep(0.0, 1.5, min(toLine.x / pxg.x, toLine.y / pxg.y));\n\n    vec3 col = 0.25 * (0.5 + 0.5 * cos(a + vec3(0.0, 2.1, 4.2)));   // hue follows the angle\n    col += lines * vec3(1.0, 0.85, 0.6);\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "flower", "label": "Example 10.6", "title": "A flower: a circle whose radius depends on the angle", "chapter": 10, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    float px = 2.0 / iResolution.y;\n\n    float r = length(uv);\n    float a = atan(uv.y, uv.x);\n\n    float petals = 5.0;                                   // try 3.0, 8.0, or 5.5\n    float edge = 0.5 + 0.15 * cos(a * petals + iTime);    // the edge's radius at this angle\n    float d = r - edge;                                   // roughly the distance to the edge\n\n    vec3 col = vec3(0.07, 0.1, 0.08);\n    vec3 petal = mix(vec3(1.0, 0.85, 0.3), vec3(0.95, 0.35, 0.45), smoothstep(0.1, 0.55, r));\n    col = mix(col, petal, 1.0 - smoothstep(-px, px, d));\n    col = mix(col, vec3(0.35, 0.2, 0.1), 1.0 - smoothstep(-px, px, r - 0.12));   // the center\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "spiral", "label": "Example 10.7", "title": "Spirals: stripes in angle and radius together", "chapter": 10, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n\n    float r = length(uv);\n    float turns = atan(uv.y, uv.x) / 6.28318;          // -0.5..0.5 for one turn around\n\n    float arms = 3.0;                                  // a whole number, because of the seam\n    float s = turns * arms + r * 2.0 - iTime * 0.3;    // constant along each spiral arm\n    float band = 0.5 + 0.5 * sin(s * 6.28318);\n\n    vec3 col = mix(vec3(0.08, 0.1, 0.25), vec3(1.0, 0.6, 0.25), band);\n    col *= smoothstep(0.0, 0.25, r);                   // fade out the crowded center\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "gear", "label": "Example 10.8", "title": "A gear: one tooth repeated 12 times, one window repeated 5 times", "chapter": 10, "passes": {"image": "float sdBox(vec2 p, vec2 b) {\n    vec2 q = abs(p) - b;\n    return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0);\n}\n\n// Fold p into the first of n slices around the center.\nvec2 repeatAngle(vec2 p, float n) {\n    float sector = 6.28318 / n;\n    float a = mod(atan(p.y, p.x) + sector * 0.5, sector) - sector * 0.5;\n    return length(p) * vec2(cos(a), sin(a));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    float px = 2.0 / iResolution.y;\n\n    float spin = iTime * 0.5;                          // turn the gear (Chapter 9)\n    vec2 p = vec2(cos(spin) * uv.x + sin(spin) * uv.y, -sin(spin) * uv.x + cos(spin) * uv.y);\n\n    vec2 t = repeatAngle(p, 12.0);\n    float tooth = sdBox(t - vec2(0.64, 0.0), vec2(0.1, 0.055)) - 0.015;   // one rounded tooth\n    float body = length(p) - 0.62;\n    float d = min(body, tooth);\n\n    vec2 w = repeatAngle(p, 5.0);\n    float window = length(w - vec2(0.36, 0.0)) - 0.11;  // one window\n    d = max(d, -window);                               // cut it out\n    d = max(d, -(length(p) - 0.1));                    // and the axle hole\n\n    vec3 col = vec3(0.08, 0.09, 0.12);\n    col = mix(col, vec3(0.8, 0.65, 0.35), 1.0 - smoothstep(-px, px, d));\n    col *= 0.85 + 0.15 * smoothstep(-0.05, 0.0, d);    // a lighter rim just inside the edge\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "kaleido", "label": "Example 10.9", "title": "Mirrored slices: a kaleidoscope over drifting discs", "chapter": 10, "passes": {"image": "// The \"colored glass\": a few discs drifting around a small area right of the center.\nvec3 picture(vec2 p) {\n    vec3 col = vec3(0.04, 0.04, 0.07);\n    for (int i = 0; i < 6; i++) {\n        float fi = float(i);\n        vec2 c = vec2(0.15 + 0.65 * (0.5 + 0.5 * sin(iTime * 0.37 + fi * 1.7)),\n                      0.22 * (0.5 + 0.5 * cos(iTime * 0.29 + fi * 2.3)));\n        float r = 0.06 + 0.04 * (0.5 + 0.5 * sin(fi * 3.1));\n        vec3 ink = 0.5 + 0.5 * cos(6.28318 * (fi * 0.15 + vec3(0.0, 0.33, 0.67)));\n        col = mix(col, ink, 1.0 - smoothstep(r, r + 0.01, length(p - c)));\n    }\n    return col;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n\n    float r = length(uv);\n    float a = atan(uv.y, uv.x);\n    float slice = 6.28318 / 8.0;              // 8 slices\n    a = mod(a, slice);                        // the angle within its slice: 0..slice\n    a = abs(a - slice * 0.5);                 // mirror each slice down its middle\n    vec2 p = r * vec2(cos(a), sin(a));        // back to x, y\n\n    vec3 col = picture(p);\n    // col = picture(uv);                     // compare: the glass without mirrors\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "fold-loop", "label": "Example 10.10", "title": "Fold, shift, turn, repeat: one ring becomes a mandala", "chapter": 10, "passes": {"image": "mat2 rot(float a) {                       // rot(a) * p turns p counterclockwise by a\n    float c = cos(a), s = sin(a);\n    return mat2(c, s, -s, c);\n}\n\nvec3 palette(float t) {\n    return 0.5 + 0.5 * cos(6.28318 * (t + vec3(0.0, 0.33, 0.67)));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    vec2 p = uv;\n\n    for (int i = 0; i < 4; i++) {         // try 1, 2, 6\n        p = abs(p);                       // fold: mirror both axes\n        p -= 0.25;                        // shift, so the next fold reflects something new\n        p = rot(0.4 + iTime * 0.1) * p;   // turn, so the next fold lands somewhere new\n    }\n\n    float d = abs(length(p) - 0.15);      // the one small ring, everything else is reflections\n    vec3 col = palette(length(uv) * 0.6 - iTime * 0.1) * 0.005 / max(d, 0.0005);\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "tunnel", "label": "Example 10.11", "title": "(angle, 1/r): flying down a tunnel", "chapter": 10, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n\n    float r = length(uv);\n    float a = atan(uv.y, uv.x);\n\n    float depth = 0.25 / r;                      // how far away this bit of wall is\n    vec2 t = vec2(a / 6.28318 * 16.0,            // 16 tiles around the tunnel (a whole number!)\n                  depth * 4.0 + iTime * 2.0);    // 4 tiles per unit of depth; time flies forward\n\n    float checker = mod(floor(t.x) + floor(t.y), 2.0);\n    vec3 col = mix(vec3(0.15, 0.25, 0.6), vec3(1.0, 0.6, 0.2), checker);\n    col *= exp(-0.35 * depth);                   // the farther away, the darker (fog)\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "hash-plot", "label": "Example 11.1", "title": "fract(sin(x) * k): a wave wiggling too fast to follow", "chapter": 11, "passes": {"image": "float f(float x, float k) {\n    return fract(sin(x) * k);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 p = fragCoord / iResolution.xy * vec2(12.0, 1.3) - vec2(0.0, 0.15);   // x 0..12, y -0.15..1.15\n    float px = 1.3 / iResolution.y;\n\n    float k = pow(43758.5453, 0.5 - 0.5 * cos(iTime * 0.3));   // sweeps 1 .. 43758.5 and back\n    // float k = 10.0;                                         // or pick one yourself\n\n    vec3 col = vec3(0.07, 0.08, 0.1);\n    col += 0.15 * (1.0 - smoothstep(0.0, px, min(abs(p.y), abs(p.y - 1.0))));  // y = 0 and y = 1\n    float y = f(p.x, k);\n    if (p.y > 0.0 && p.y < y) col += vec3(1.0, 0.65, 0.2) * 0.25;             // shade under the curve\n    col = mix(col, vec3(1.0, 0.65, 0.2), 1.0 - smoothstep(0.0, 3.0 * px, abs(p.y - y)));\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "hash-tiles", "label": "Example 11.2", "title": "Random per tile (left), re-rolled each second (middle), per pixel per frame (right)", "chapter": 11, "passes": {"image": "float hash(vec2 p) {\n    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.y;\n    vec2 id = floor(uv * 8.0);                         // 8 tiles per unit of height\n    float panel = floor(fragCoord.x / (iResolution.x / 3.0));\n\n    float r;\n    if (panel == 0.0)      r = hash(id);                         // fixed forever\n    else if (panel == 1.0) r = hash(id + floor(iTime));          // new roll each second\n    else                   r = hash(fragCoord + fract(iTime) * 100.0);   // every pixel, every frame\n\n    vec3 col = vec3(r);\n    if (mod(fragCoord.x, iResolution.x / 3.0) < 2.0) col = vec3(1.0, 0.6, 0.2);   // dividers\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "truchet", "label": "Example 11.3", "title": "Truchet tiles: a random flip per tile makes a maze", "chapter": 11, "passes": {"image": "float hash(vec2 p) {\n    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    float px = 2.0 * 4.0 / iResolution.y;\n    uv = uv * 4.0 + iTime * 0.2;                 // 4 tiles per unit, drifting\n\n    vec2 id = floor(uv);\n    vec2 p = fract(uv) - 0.5;\n\n    if (hash(id) < 0.5) p.x = -p.x;              // flip a random half of the tiles (a mirror!)\n\n    // two arcs: quarter circles of radius 0.5 around opposite corners\n    float d = min(abs(length(p - 0.5) - 0.5), abs(length(p + 0.5) - 0.5));\n    float line = 1.0 - smoothstep(0.07 - px, 0.07 + px, d);\n\n    vec3 col = mix(vec3(0.08, 0.09, 0.12), vec3(1.0, 0.75, 0.4), line);\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "value-noise", "label": "Example 11.4", "title": "Value noise: random corners, smoothly blended", "chapter": 11, "passes": {"image": "float hash(vec2 p) {\n    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);\n}\n\nfloat noise(vec2 p) {\n    vec2 i = floor(p);                    // which tile\n    vec2 f = fract(p);                    // where inside it, 0..1\n    vec2 u = f * f * (3.0 - 2.0 * f);     // the smooth blend curve (try u = f)\n\n    float a = hash(i);                    // the four corners' random values\n    float b = hash(i + vec2(1.0, 0.0));\n    float c = hash(i + vec2(0.0, 1.0));\n    float d = hash(i + vec2(1.0, 1.0));\n\n    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);   // bottom edge, top edge, then up\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.y;\n    vec2 p = uv * 8.0 + vec2(iTime * 0.5, 0.0);\n\n    float n = noise(p);\n    if (uv.x < 0.4) n = hash(floor(p));   // left strip: the raw random tiles it's built from\n\n    fragColor = vec4(vec3(n), 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "noise-compare", "label": "Example 11.5", "title": "Value noise (left) and gradient noise (right), same grid", "chapter": 11, "passes": {"image": "float hash(vec2 p) {\n    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);\n}\n\nfloat vnoise(vec2 p) {\n    vec2 i = floor(p), f = fract(p);\n    vec2 u = f * f * (3.0 - 2.0 * f);\n    return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),\n               mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nvec2 grad(vec2 corner) {\n    float a = hash(corner) * 6.28318;\n    return vec2(cos(a), sin(a));\n}\n\nfloat gnoise(vec2 p) {\n    vec2 i = floor(p), f = fract(p);\n    vec2 u = f * f * (3.0 - 2.0 * f);\n    float a = dot(grad(i + vec2(0.0, 0.0)), f - vec2(0.0, 0.0));\n    float b = dot(grad(i + vec2(1.0, 0.0)), f - vec2(1.0, 0.0));\n    float c = dot(grad(i + vec2(0.0, 1.0)), f - vec2(0.0, 1.0));\n    float d = dot(grad(i + vec2(1.0, 1.0)), f - vec2(1.0, 1.0));\n    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.y;\n    vec2 p = uv * 6.0 + vec2(0.0, iTime * 0.3);\n\n    float n = fragCoord.x < iResolution.x * 0.5\n        ? vnoise(p)                         // 0..1\n        : gnoise(p) * 0.7 + 0.5;            // about -0.7..0.7, moved to 0..1\n\n    vec3 col = vec3(n);\n    vec2 g = abs(fract(p + 0.5) - 0.5);     // faint grid lines, to compare against\n    col = mix(col, vec3(1.0, 0.6, 0.2), 0.35 * (1.0 - smoothstep(0.0, 0.02, min(g.x, g.y))));\n    if (abs(fragCoord.x - iResolution.x * 0.5) < 1.5) col = vec3(1.0);\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "fbm", "label": "Example 11.6", "title": "fBm: six octaves of noise make clouds", "chapter": 11, "passes": {"image": "float hash(vec2 p) {\n    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);\n}\n\nfloat noise(vec2 p) {\n    vec2 i = floor(p), f = fract(p);\n    vec2 u = f * f * (3.0 - 2.0 * f);\n    return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),\n               mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nfloat fbm(vec2 p) {\n    float sum = 0.0, amp = 0.5;\n    for (int i = 0; i < 6; i++) {          // try 1, 2, 3 octaves to see the layers build up\n        sum += amp * noise(p);\n        p *= 2.0;\n        amp *= 0.5;\n    }\n    return sum;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.y;\n    float n = fbm(uv * 3.0 + vec2(iTime * 0.1, 0.0));\n\n    vec3 sky = mix(vec3(0.25, 0.45, 0.85), vec3(0.6, 0.75, 0.95), uv.y);\n    vec3 col = mix(sky, vec3(1.0), smoothstep(0.45, 0.8, n));   // only the high values are cloud\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "materials", "label": "Example 11.7", "title": "Wood (left) and marble (right): noise bending simple patterns", "chapter": 11, "passes": {"image": "float hash(vec2 p) {\n    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);\n}\n\nfloat noise(vec2 p) {\n    vec2 i = floor(p), f = fract(p);\n    vec2 u = f * f * (3.0 - 2.0 * f);\n    return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),\n               mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nfloat fbm(vec2 p) {\n    float sum = 0.0, amp = 0.5;\n    for (int i = 0; i < 5; i++) { sum += amp * noise(p); p *= 2.0; amp *= 0.5; }\n    return sum;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.y;\n    vec3 col;\n    if (fragCoord.x < iResolution.x * 0.5) {\n        // wood: rings around a point below the canvas, stretched sideways, wobbled by noise\n        vec2 p = (uv - vec2(0.4, -1.5)) * vec2(0.3, 1.0);\n        float rings = length(p) * 14.0 + noise(uv * vec2(4.0, 16.0)) * 1.2;\n        float grain = fract(rings);\n        col = mix(vec3(0.55, 0.32, 0.15), vec3(0.8, 0.55, 0.3), smoothstep(0.0, 0.8, grain));\n    } else {\n        // marble: a sine wave whose position is pushed around by fBm\n        float v = sin(uv.x * 10.0 + uv.y * 4.0 + fbm(uv * 4.0) * 7.0);\n        col = mix(vec3(0.95, 0.94, 0.9), vec3(0.3, 0.33, 0.38), pow(1.0 - abs(v), 6.0));\n    }\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "warp", "label": "Example 11.8", "title": "Domain warping: fbm(p + 4 · fbm(p + 4 · fbm(p)))", "chapter": 11, "passes": {"image": "float hash(vec2 p) {\n    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);\n}\n\nfloat noise(vec2 p) {\n    vec2 i = floor(p), f = fract(p);\n    vec2 u = f * f * (3.0 - 2.0 * f);\n    return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),\n               mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nfloat fbm(vec2 p) {\n    float sum = 0.0, amp = 0.5;\n    for (int i = 0; i < 5; i++) { sum += amp * noise(p); p *= 2.0; amp *= 0.5; }\n    return sum;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 p = fragCoord / iResolution.y * 3.0;\n    float t = iTime * 0.1;\n\n    // first warp: q is a 2D offset made of two fbm lookups\n    vec2 q = vec2(fbm(p + vec2(0.0, 0.0) + t),\n                  fbm(p + vec2(5.2, 1.3) - t));\n    // second warp: r is computed at the already-pushed position\n    vec2 r = vec2(fbm(p + 4.0 * q + vec2(1.7, 9.2)),\n                  fbm(p + 4.0 * q + vec2(8.3, 2.8)));\n    float f = fbm(p + 4.0 * r);\n\n    // the in-between values q and r make good color inputs too\n    vec3 col = mix(vec3(0.10, 0.12, 0.30), vec3(0.95, 0.55, 0.25), clamp(f * f * 2.5, 0.0, 1.0));\n    col = mix(col, vec3(0.05, 0.35, 0.40), clamp(length(q) - 0.6, 0.0, 1.0));\n    col = mix(col, vec3(1.0, 0.92, 0.8), clamp(r.x * r.x, 0.0, 1.0) * 0.5);\n    fragColor = vec4(col * (0.5 + f), 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "voronoi", "label": "Example 11.9", "title": "Voronoi: the nearest of nine random points", "chapter": 11, "passes": {"image": "vec2 hash2(vec2 p) {                       // two random numbers for one input\n    p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));\n    return fract(sin(p) * 43758.5453);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 p = fragCoord / iResolution.y * 6.0;\n    vec2 id = floor(p);\n    vec2 f = fract(p);\n\n    float d1 = 8.0, d2 = 8.0;              // nearest and second-nearest distances so far\n    vec2 nearest = vec2(0.0);\n    for (int y = -1; y <= 1; y++)\n    for (int x = -1; x <= 1; x++) {\n        vec2 nb = vec2(float(x), float(y));                   // a neighboring tile\n        vec2 pt = hash2(id + nb);                             // its random point, 0..1 in that tile\n        pt = 0.5 + 0.4 * sin(iTime * 0.8 + 6.28318 * pt);     // let the points drift\n        float d = length(nb + pt - f);                        // from this pixel to that point\n        if (d < d1) { d2 = d1; d1 = d; nearest = id + nb; }\n        else if (d < d2) { d2 = d; }\n    }\n\n    vec3 cell = 0.5 + 0.5 * cos(6.28318 * (hash2(nearest).x + vec3(0.0, 0.33, 0.67)));\n    vec3 col = cell * (1.0 - 0.6 * d1);                       // darker away from the point\n    col *= smoothstep(0.02, 0.06, d2 - d1);                   // dark borders where d1 ≈ d2\n    // col = vec3(d1);                                        // just the distance: bubbles\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "step-rings", "label": "Example 12.1", "title": "Step 1: rings around the center, made to glow", "chapter": 12, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;   // Chapter 3\n\n    float d = length(uv);                 // distance from the center (Chapter 7)\n    d = sin(d * 8.0 + iTime) / 8.0;       // ripples: a wave travelling through the distance (Chapter 5)\n    d = abs(d);                           // distance to the nearest ripple (Chapter 8)\n    d = 0.02 / d;                         // glow: very bright near each ripple (Chapter 8)\n\n    fragColor = vec4(vec3(d), 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "step-repeat", "label": "Example 12.2", "title": "Step 2: repetition, a fade and a palette", "chapter": 12, "passes": {"image": "vec3 palette(float t) {                        // Chapter 6\n    vec3 a = vec3(0.5, 0.5, 0.5);\n    vec3 b = vec3(0.5, 0.5, 0.5);\n    vec3 c = vec3(1.0, 1.0, 1.0);\n    vec3 d = vec3(0.263, 0.416, 0.557);\n    return a + b * cos(6.28318 * (c * t + d));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    vec2 uv0 = uv;                             // remember where this pixel started\n\n    uv = fract(uv * 2.0) - 0.5;                // repeat space (Chapter 10)\n\n    float d = length(uv) * exp(-length(uv0));  // rings in each tile, shrinking toward the edges\n    vec3 col = palette(length(uv0) + iTime * 0.4);   // color by the ORIGINAL distance\n\n    d = sin(d * 8.0 + iTime) / 8.0;\n    d = abs(d);\n    d = 0.02 / d;\n\n    fragColor = vec4(col * d, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "first-piece", "label": "Example 12.3", "title": "Step 3: four layers, each folding the last", "chapter": 12, "passes": {"image": "// After kishimisu's \"An introduction to Shader Art Coding\".\n\nvec3 palette(float t) {                                  // Chapter 6\n    vec3 a = vec3(0.5, 0.5, 0.5);\n    vec3 b = vec3(0.5, 0.5, 0.5);\n    vec3 c = vec3(1.0, 1.0, 1.0);\n    vec3 d = vec3(0.263, 0.416, 0.557);\n    return a + b * cos(6.28318 * (c * t + d));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;   // Chapter 3\n    vec2 uv0 = uv;                          // where this pixel started\n    vec3 finalColor = vec3(0.0);\n\n    for (float i = 0.0; i < 4.0; i++) {\n        uv = fract(uv * 1.5) - 0.5;         // repeat the space left by the last layer (Chapter 10)\n\n        float d = length(uv) * exp(-length(uv0));                 // distance, fading outward\n        vec3 col = palette(length(uv0) + i * 0.4 + iTime * 0.4);  // each layer a bit further along\n\n        d = sin(d * 8.0 + iTime) / 8.0;     // ripples (Chapter 5)\n        d = abs(d);\n        d = pow(0.01 / d, 1.2);             // glow, with extra contrast (Chapter 8)\n\n        finalColor += col * d;              // light adds up (Chapter 6)\n    }\n\n    fragColor = vec4(finalColor, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "variation", "label": "Example 12.4", "title": "A variation: fold, turn, square distance, tone mapping", "chapter": 12, "passes": {"image": "mat2 rot(float a) {                        // rot(a) * p turns p by a (Chapter 9)\n    float c = cos(a), s = sin(a);\n    return mat2(c, s, -s, c);\n}\n\nvec3 palette(float t) {\n    vec3 a = vec3(0.5, 0.5, 0.5);\n    vec3 b = vec3(0.5, 0.5, 0.5);\n    vec3 c = vec3(1.0, 1.0, 0.5);\n    vec3 d = vec3(0.80, 0.90, 0.30);       // a warmer palette\n    return a + b * cos(6.28318 * (c * t + d));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    vec2 uv0 = uv;\n    vec3 finalColor = vec3(0.0);\n\n    for (float i = 0.0; i < 4.0; i++) {\n        uv = abs(uv);                                   // NEW: mirror (Chapter 10)\n        uv = rot(iTime * 0.1 + i * 0.7) * uv;           // NEW: turn each layer differently\n        uv = fract(uv * 1.4) - 0.5;\n\n        float d = max(abs(uv.x), abs(uv.y)) * exp(-length(uv0));   // NEW: square distance\n        vec3 col = palette(length(uv0) + i * 0.3 + iTime * 0.3);\n\n        d = sin(d * 10.0 + iTime) / 10.0;\n        d = abs(d);\n        d = pow(0.008 / d, 1.3);\n\n        finalColor += col * d;\n    }\n    finalColor = 1.0 - exp(-finalColor);                // NEW: tone map (Chapter 6)\n    fragColor = vec4(finalColor, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "finishing", "label": "Example 12.5", "title": "Raw (left) and finished (right): aberration, tone map, vignette, grain", "chapter": 12, "passes": {"image": "vec3 palette(float t) {\n    return 0.5 + 0.5 * cos(6.28318 * (t + vec3(0.263, 0.416, 0.557)));\n}\n\nfloat hash(vec2 p) {\n    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);\n}\n\n// The piece, as a function of position, so it can be computed more than once.\nvec3 scene(vec2 uv) {\n    float a = atan(uv.y, uv.x);\n    float d = abs(length(uv) - 0.55 - 0.06 * sin(a * 6.0 + iTime));   // a wobbly ring\n    d = min(d, abs(length(uv) - 0.25));                                 // and a small one\n    return palette(length(uv) * 0.6 + iTime * 0.1) * 0.035 / d;         // glowing\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    vec3 col = scene(uv);\n\n    if (fragCoord.x > iResolution.x * 0.5) {\n        // 1. chromatic aberration: red sampled a little bigger, blue a little smaller\n        col = vec3(scene(uv * 0.985).r, scene(uv).g, scene(uv * 1.015).b);\n        // 2. tone map\n        col = 1.0 - exp(-col);\n        // 3. vignette: 1 in the middle, darker toward the corners\n        col *= 1.0 - 0.6 * smoothstep(0.5, 2.0, length(uv));\n        // 4. grain: a little noise, different every frame\n        col += (hash(fragCoord + fract(iTime) * 97.0) - 0.5) * 0.05;\n    }\n    if (abs(fragCoord.x - iResolution.x * 0.5) < 1.0) col = vec3(0.4);   // the dividing line\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "loop", "label": "Example 12.6", "title": "A perfect 6-second loop", "chapter": 12, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    float px = 2.0 / iResolution.y;\n\n    float period = 6.0;                        // seconds per loop\n    float t = fract(iTime / period);           // 0 → 1 over one loop, then starts again\n    float a = t * 6.28318;                     // the same as an angle: one full turn per loop\n\n    vec3 col = vec3(0.06, 0.05, 0.09);\n    for (int i = 0; i < 12; i++) {\n        float fi = float(i) / 12.0;\n        float ang = fi * 6.28318 + a;                    // the ring turns exactly once per loop\n        float wave = sin(2.0 * a - fi * 6.28318 * 3.0);  // two whole waves per loop\n        vec2 c = (0.55 + 0.15 * wave) * vec2(cos(ang), sin(ang));\n        float d = length(uv - c) - (0.06 + 0.03 * wave);\n        vec3 ink = 0.5 + 0.5 * cos(6.28318 * (fi + vec3(0.0, 0.33, 0.67)));\n        col = mix(col, ink, 1.0 - smoothstep(-px, px, d));\n    }\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "ray-dirs", "label": "Example 13.1", "title": "The camera's rays, as colors", "chapter": 13, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n\n    float f = 1.5 + sin(iTime);              // focal length: watch the field of view change\n    vec3 rd = normalize(vec3(uv, f));        // this pixel's ray direction (length 1)\n\n    fragColor = vec4(rd * 0.5 + 0.5, 1.0);   // -1..1 shown as 0..1\n}", "buffer": null}, "cfg": {}}, {"id": "first-hit", "label": "Example 13.2", "title": "The first raymarcher: did the ray hit anything?", "chapter": 13, "passes": {"image": "float map(vec3 p) {\n    return length(p) - 1.0;                 // a sphere of radius 1 at the origin\n}\n\nfloat march(vec3 ro, vec3 rd) {\n    float t = 0.0;\n    for (int i = 0; i < 100; i++) {\n        vec3 p = ro + rd * t;\n        float d = map(p);\n        if (d < 0.001) return t;\n        t += d;\n        if (t > 20.0) break;\n    }\n    return -1.0;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n\n    vec3 ro = vec3(0.0, 0.0, -3.0);         // the eye, 3 units in front of the sphere\n    vec3 rd = normalize(vec3(uv, 1.5));     // this pixel's ray\n\n    float t = march(ro, rd);\n    vec3 col = t > 0.0 ? vec3(1.0) : vec3(0.0);   // hit: white, miss: black\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "depth", "label": "Example 13.3", "title": "Depth: brighter means nearer", "chapter": 13, "passes": {"image": "float sdBox(vec3 p, vec3 b) {\n    vec3 q = abs(p) - b;\n    return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);\n}\n\nfloat map(vec3 p) {\n    float sphere = length(p - vec3(-1.0, 0.0, 0.0)) - 1.0;\n    float box = sdBox(p - vec3(1.3, -0.4, 0.5), vec3(0.6));\n    float ground = p.y + 1.0;                       // a floor at y = -1\n    return min(min(sphere, box), ground);           // union of all three (Chapter 8)\n}\n\nfloat march(vec3 ro, vec3 rd) {\n    float t = 0.0;\n    for (int i = 0; i < 100; i++) {\n        float d = map(ro + rd * t);\n        if (d < 0.001) return t;\n        t += d;\n        if (t > 20.0) break;\n    }\n    return -1.0;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    vec3 ro = vec3(0.0, 0.5, -4.0);                 // a little up and back\n    vec3 rd = normalize(vec3(uv, 1.5));\n\n    float t = march(ro, rd);\n    vec3 col = vec3(0.0);\n    if (t > 0.0) col = vec3(1.0 - t / 10.0);        // 1 right at the eye, 0 at 10 units away\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "steps", "label": "Example 13.4", "title": "Cost: how many steps each ray took (dark = few, bright = many)", "chapter": 13, "passes": {"image": "float map(vec3 p) {\n    float sphere = length(p - vec3(-1.0, 0.0, 0.0)) - 1.0;\n    float sphere2 = length(p - vec3(1.3, -0.3, 0.5)) - 0.7;\n    float ground = p.y + 1.0;\n    return min(min(sphere, sphere2), ground);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    vec3 ro = vec3(0.0, 0.5, -4.0);\n    vec3 rd = normalize(vec3(uv, 1.5));\n\n    float t = 0.0, steps = 0.0;\n    for (int i = 0; i < 100; i++) {\n        float d = map(ro + rd * t);\n        if (d < 0.001 || t > 20.0) break;\n        t += d;\n        steps += 1.0;\n    }\n    float heat = steps / 100.0;                     // 0..1\n    vec3 col = vec3(heat * 3.0, heat * 1.5, heat * 0.6);   // black → orange → white\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "normals", "label": "Example 13.5", "title": "Surface normals, shown as colors", "chapter": 13, "passes": {"image": "float sdBox(vec3 p, vec3 b) {\n    vec3 q = abs(p) - b;\n    return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);\n}\n\nfloat map(vec3 p) {\n    float sphere = length(p - vec3(-1.0, 0.0, 0.0)) - 1.0;\n    float box = sdBox(p - vec3(1.3, -0.4, 0.5), vec3(0.6)) - 0.05;   // slightly rounded\n    float ground = p.y + 1.0;\n    return min(min(sphere, box), ground);\n}\n\nfloat march(vec3 ro, vec3 rd) {\n    float t = 0.0;\n    for (int i = 0; i < 100; i++) {\n        float d = map(ro + rd * t);\n        if (d < 0.001) return t;\n        t += d;\n        if (t > 20.0) break;\n    }\n    return -1.0;\n}\n\nvec3 calcNormal(vec3 p) {\n    vec2 e = vec2(0.001, 0.0);\n    return normalize(vec3(map(p + e.xyy) - map(p - e.xyy),\n                          map(p + e.yxy) - map(p - e.yxy),\n                          map(p + e.yyx) - map(p - e.yyx)));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    vec3 ro = vec3(0.0, 0.5, -4.0);\n    vec3 rd = normalize(vec3(uv, 1.5));\n\n    float t = march(ro, rd);\n    vec3 col = vec3(0.0);\n    if (t > 0.0) {\n        vec3 n = calcNormal(ro + rd * t);       // the surface's direction at the hit point\n        col = n * 0.5 + 0.5;                    // -1..1 shown as 0..1\n    }\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "lit-scene", "label": "Example 13.6", "title": "A lit scene: diffuse, ambient, specular and materials", "chapter": 13, "passes": {"image": "mat2 rot(float a) {\n    float c = cos(a), s = sin(a);\n    return mat2(c, s, -s, c);\n}\n\nfloat sdBox(vec3 p, vec3 b) {\n    vec3 q = abs(p) - b;\n    return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);\n}\n\n// The scene: returns (distance to the nearest surface, which material it is).\nvec2 map(vec3 p) {\n    vec2 res = vec2(p.y + 1.0, 0.0);                            // 0: the ground\n    float sphere = length(p - vec3(-1.1, 0.0, 0.0)) - 1.0;\n    if (sphere < res.x) res = vec2(sphere, 1.0);                // 1: the sphere\n    vec3 q = p - vec3(1.3, -0.35, 0.4);\n    q.xz = rot(iTime * 0.5) * q.xz;                             // spin the box around y (Chapter 9)\n    float box = sdBox(q, vec3(0.6)) - 0.05;\n    if (box < res.x) res = vec2(box, 2.0);                      // 2: the box\n    return res;\n}\n\nvec2 march(vec3 ro, vec3 rd) {\n    float t = 0.0;\n    for (int i = 0; i < 120; i++) {\n        vec2 h = map(ro + rd * t);\n        if (h.x < 0.001) return vec2(t, h.y);                   // hit: distance and material\n        t += h.x;\n        if (t > 30.0) break;\n    }\n    return vec2(-1.0);\n}\n\nvec3 calcNormal(vec3 p) {\n    vec2 e = vec2(0.001, 0.0);\n    return normalize(vec3(map(p + e.xyy).x - map(p - e.xyy).x,\n                          map(p + e.yxy).x - map(p - e.yxy).x,\n                          map(p + e.yyx).x - map(p - e.yyx).x));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    vec3 ro = vec3(0.0, 0.6, -4.5);\n    vec3 rd = normalize(vec3(uv, 1.6));\n\n    vec3 sky = mix(vec3(0.55, 0.65, 0.8), vec3(0.2, 0.3, 0.55), clamp(rd.y * 2.0, 0.0, 1.0));\n    vec3 col = sky;                                             // what misses see\n\n    vec2 hit = march(ro, rd);\n    if (hit.x > 0.0) {\n        vec3 p = ro + rd * hit.x;                               // the hit point\n        vec3 n = calcNormal(p);\n\n        vec3 albedo = vec3(0.6);                                // the surface's own color\n        if (hit.y == 0.0) albedo = vec3(0.35) + 0.15 * mod(floor(p.x) + floor(p.z), 2.0);  // checker\n        if (hit.y == 1.0) albedo = vec3(0.8, 0.3, 0.15);\n        if (hit.y == 2.0) albedo = vec3(0.2, 0.45, 0.85);\n\n        vec3 lightDir = normalize(vec3(0.6, 0.8, -0.5));        // toward the sun\n        float diff = max(dot(n, lightDir), 0.0);\n        float amb = 0.5 + 0.5 * n.y;\n        vec3 h = normalize(lightDir - rd);\n        float spec = pow(max(dot(n, h), 0.0), 64.0) * diff;     // no highlight on the dark side\n\n        col = albedo * (diff * vec3(1.0, 0.92, 0.8) + amb * vec3(0.12, 0.16, 0.25));\n        col += spec * 0.5;\n        col = mix(col, sky, 1.0 - exp(-0.004 * hit.x * hit.x)); // a hint of distance haze\n    }\n    col = pow(col, vec3(1.0 / 2.2));                            // gamma (Chapter 6)\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "shadows", "label": "Example 14.1", "title": "Hard shadows (left) and soft shadows (right)", "chapter": 14, "passes": {"image": "float map(vec3 p) {\n    float a = length(p - vec3(-0.9, 0.7, 0.0)) - 0.7;\n    float b = length(p - vec3(1.0, 0.5 + 0.3 * sin(iTime), 0.4)) - 0.5;\n    float pillar = length(p.xz - vec2(0.1, 1.2)) - 0.15;    // an infinitely tall cylinder...\n    pillar = max(pillar, p.y - 2.0);                         // ...cut off at y = 2\n    return min(min(min(a, b), pillar), p.y);                 // p.y: the ground at y = 0\n}\n\nvec3 calcNormal(vec3 p) {\n    vec2 e = vec2(0.001, 0.0);\n    return normalize(vec3(map(p + e.xyy) - map(p - e.xyy),\n                          map(p + e.yxy) - map(p - e.yxy),\n                          map(p + e.yyx) - map(p - e.yyx)));\n}\n\nfloat hardShadow(vec3 p, vec3 l) {\n    float t = 0.02;\n    for (int i = 0; i < 64; i++) {\n        float h = map(p + l * t);\n        if (h < 0.001) return 0.0;\n        t += h;\n        if (t > 10.0) break;\n    }\n    return 1.0;\n}\n\nfloat softShadow(vec3 p, vec3 l, float k) {\n    float res = 1.0, t = 0.02;\n    for (int i = 0; i < 64; i++) {\n        float h = map(p + l * t);\n        res = min(res, k * h / t);\n        if (res < 0.001) break;\n        t += clamp(h, 0.01, 0.25);\n        if (t > 10.0) break;\n    }\n    return clamp(res, 0.0, 1.0);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    bool soft = uv.x > 0.0;                                   // right half: soft shadows\n    float halfW = iResolution.x / iResolution.y;              // each half is this wide in uv units\n    uv.x += soft ? -0.5 * halfW : 0.5 * halfW;                // center each half: two views of one scene\n\n    vec3 ro = vec3(0.0, 2.2, -6.0);\n    vec3 rd = normalize(vec3(uv.x, uv.y - 0.35, 1.8));        // tilted down a little\n\n    float t = 0.0;\n    for (int i = 0; i < 120; i++) {\n        float d = map(ro + rd * t);\n        if (d < 0.001 || t > 30.0) break;\n        t += d;\n    }\n\n    vec3 col = vec3(0.6, 0.7, 0.85);                          // sky\n    if (t < 30.0) {\n        vec3 p = ro + rd * t;\n        vec3 n = calcNormal(p);\n        vec3 l = normalize(vec3(-0.8, 0.5, -0.2));            // toward a low sun, on the left\n        float sh = soft ? softShadow(p, l, 8.0) : hardShadow(p, l);\n        float diff = max(dot(n, l), 0.0) * sh;\n        col = vec3(0.8) * (diff * vec3(1.0, 0.9, 0.75) + (0.5 + 0.5 * n.y) * vec3(0.15, 0.2, 0.3));\n    }\n    if (abs(fragCoord.x - iResolution.x * 0.5) < 1.5) col = vec3(1.0, 0.6, 0.2);   // the divider\n    fragColor = vec4(pow(col, vec3(1.0 / 2.2)), 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "ao-view", "label": "Example 14.2", "title": "Ambient occlusion only: white where the surface sees the open sky", "chapter": 14, "passes": {"image": "float smin(float a, float b, float k) {\n    float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);\n    return mix(b, a, h) - k * h * (1.0 - h);\n}\n\nfloat sdBox(vec3 p, vec3 b) {\n    vec3 q = abs(p) - b;\n    return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);\n}\n\nfloat map(vec3 p) {\n    float a = length(p - vec3(-0.6, 0.55, 0.0)) - 0.6;\n    float b = length(p - vec3(0.35, 0.4 + 0.15 * sin(iTime), -0.3)) - 0.45;\n    float blob = smin(a, b, 0.2);\n    float wall = sdBox(p - vec3(0.0, 1.0, 1.0), vec3(3.0, 1.0, 0.1));   // a wall behind\n    return min(min(blob, wall), p.y);\n}\n\nvec3 calcNormal(vec3 p) {\n    vec2 e = vec2(0.001, 0.0);\n    return normalize(vec3(map(p + e.xyy) - map(p - e.xyy),\n                          map(p + e.yxy) - map(p - e.yxy),\n                          map(p + e.yyx) - map(p - e.yyx)));\n}\n\nfloat occlusion(vec3 p, vec3 n) {\n    float occ = 0.0, w = 1.0;\n    for (int i = 1; i <= 5; i++) {\n        float h = 0.02 + 0.06 * float(i);\n        occ += (h - map(p + n * h)) * w;\n        w *= 0.7;\n    }\n    return clamp(1.0 - 2.5 * occ, 0.0, 1.0);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    vec3 ro = vec3(0.4, 1.4, -3.2);\n    vec3 rd = normalize(vec3(uv.x, uv.y - 0.3, 1.6));\n\n    float t = 0.0;\n    for (int i = 0; i < 120; i++) {\n        float d = map(ro + rd * t);\n        if (d < 0.001 || t > 20.0) break;\n        t += d;\n    }\n    vec3 col = vec3(0.9);\n    if (t < 20.0) {\n        vec3 p = ro + rd * t;\n        col = vec3(occlusion(p, calcNormal(p)));\n    }\n    fragColor = vec4(pow(col, vec3(1.0 / 2.2)), 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "mood", "label": "Example 14.3", "title": "A sculpture at golden hour: shadows, AO, fog and an orbiting camera", "chapter": 14, "passes": {"image": "float smin(float a, float b, float k) {\n    float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);\n    return mix(b, a, h) - k * h * (1.0 - h);\n}\n\nfloat map(vec3 p) {\n    float a = length(p - vec3(0.0, 0.8, 0.0)) - 0.8;\n    float b = length(p - vec3(0.9 * sin(iTime * 0.7), 0.5 + 0.3 * sin(iTime * 1.3), 0.6 * cos(iTime * 0.7))) - 0.45;\n    float c = length(p - vec3(-1.1, 0.35, 0.4)) - 0.35;\n    float sculpture = smin(smin(a, b, 0.4), c, 0.3);\n    return min(sculpture, p.y);                         // p.y: the ground\n}\n\nvec3 calcNormal(vec3 p) {\n    vec2 e = vec2(0.001, 0.0);\n    return normalize(vec3(map(p + e.xyy) - map(p - e.xyy),\n                          map(p + e.yxy) - map(p - e.yxy),\n                          map(p + e.yyx) - map(p - e.yyx)));\n}\n\nfloat softShadow(vec3 p, vec3 l, float k) {\n    float res = 1.0, t = 0.02;\n    for (int i = 0; i < 48; i++) {\n        float h = map(p + l * t);\n        res = min(res, k * h / t);\n        if (res < 0.001) break;\n        t += clamp(h, 0.02, 0.25);\n        if (t > 8.0) break;\n    }\n    return clamp(res, 0.0, 1.0);\n}\n\nfloat occlusion(vec3 p, vec3 n) {\n    float occ = 0.0, w = 1.0;\n    for (int i = 1; i <= 5; i++) {\n        float h = 0.02 + 0.06 * float(i);\n        occ += (h - map(p + n * h)) * w;\n        w *= 0.7;\n    }\n    return clamp(1.0 - 2.5 * occ, 0.0, 1.0);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n\n    // a camera that orbits the sculpture and looks at it\n    float ang = iTime * 0.15;\n    vec3 ro = vec3(4.0 * sin(ang), 1.6, -4.0 * cos(ang));\n    vec3 target = vec3(0.0, 0.6, 0.0);\n    vec3 fw = normalize(target - ro);\n    vec3 rt = normalize(cross(vec3(0.0, 1.0, 0.0), fw));\n    vec3 up = cross(fw, rt);\n    vec3 rd = normalize(uv.x * rt + uv.y * up + 1.8 * fw);\n\n    float t = 0.0;\n    for (int i = 0; i < 120; i++) {\n        float d = map(ro + rd * t);\n        if (d < 0.001 || t > 30.0) break;\n        t += d;\n    }\n\n    vec3 sunDir = normalize(vec3(-0.6, 0.45, 0.5));    // a low, golden sun\n    vec3 sky = mix(vec3(1.0, 0.72, 0.48), vec3(0.32, 0.42, 0.68), clamp(rd.y * 2.0 + 0.3, 0.0, 1.0));\n    sky += vec3(1.0, 0.6, 0.3) * pow(max(dot(rd, sunDir), 0.0), 24.0);   // glow around the sun\n    vec3 col = sky;\n    if (t < 30.0) {\n        vec3 p = ro + rd * t;\n        vec3 n = calcNormal(p);\n        float sun = max(dot(n, sunDir), 0.0) * softShadow(p, sunDir, 8.0);\n        float skyLight = 0.5 + 0.5 * n.y;\n        float ao = occlusion(p, n);\n        vec3 albedo = p.y < 0.002 ? vec3(0.5, 0.46, 0.42) : vec3(0.85, 0.32, 0.22);\n        col = albedo * (vec3(1.7, 1.15, 0.75) * sun + vec3(0.22, 0.3, 0.45) * skyLight * ao);\n        col = mix(col, sky, 1.0 - exp(-0.004 * t * t));   // fog\n    }\n    fragColor = vec4(pow(col, vec3(1.0 / 2.2)), 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "infinite", "label": "Example 14.4", "title": "An endless lattice: one ball and one rod, repeated forever", "chapter": 14, "passes": {"image": "float smin(float a, float b, float k) {\n    float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);\n    return mix(b, a, h) - k * h * (1.0 - h);\n}\n\nfloat map(vec3 p) {\n    p.z += iTime;                          // move the world toward the camera: flying forward\n    vec3 q = mod(p + 1.0, 2.0) - 1.0;      // repeat space every 2 units (Chapter 10, in 3D)\n    float ball = length(q) - 0.35;\n    float rod = length(q.xy) - 0.06;       // a thin rod along z in every cell\n    return smin(ball, rod, 0.15);          // melt them together (Chapter 8)\n}\n\nvec3 calcNormal(vec3 p) {\n    vec2 e = vec2(0.001, 0.0);\n    return normalize(vec3(map(p + e.xyy) - map(p - e.xyy),\n                          map(p + e.yxy) - map(p - e.yxy),\n                          map(p + e.yyx) - map(p - e.yyx)));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    vec3 ro = vec3(1.0, 1.0, 0.0);         // between the rods\n    vec3 rd = normalize(vec3(uv, 1.2));\n\n    float t = 0.0;\n    for (int i = 0; i < 100; i++) {\n        float d = map(ro + rd * t);\n        if (d < 0.001 || t > 30.0) break;\n        t += d;\n    }\n\n    vec3 fog = vec3(0.06, 0.07, 0.12);\n    vec3 col = fog;\n    if (t < 30.0) {\n        vec3 p = ro + rd * t;\n        vec3 n = calcNormal(p);\n        float diff = max(dot(n, normalize(vec3(0.5, 0.8, -0.4))), 0.0);\n        vec3 base = 0.55 + 0.45 * cos(6.28318 * (t * 0.04 + vec3(0.0, 0.33, 0.67)));\n        col = base * (0.15 + 0.85 * diff);\n        col = mix(col, fog, 1.0 - exp(-0.012 * t * t));   // fog hides where it stops being drawn\n    }\n    fragColor = vec4(pow(col, vec3(1.0 / 2.2)), 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "twist", "label": "Example 14.5", "title": "A twisted column and a displaced ball, with careful steps", "chapter": 14, "passes": {"image": "mat2 rot(float a) {\n    float c = cos(a), s = sin(a);\n    return mat2(c, s, -s, c);\n}\n\nfloat sdBox(vec3 p, vec3 b) {\n    vec3 q = abs(p) - b;\n    return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);\n}\n\nfloat map(vec3 p) {\n    vec3 q = p - vec3(-0.9, 0.0, 0.0);\n    q.xz = rot(q.y * 1.5 * sin(iTime * 0.5)) * q.xz;     // twist: each height turns by its own angle\n    float column = sdBox(q, vec3(0.4, 1.4, 0.4)) - 0.04;\n\n    vec3 s = p - vec3(0.9, 0.0, 0.0);\n    float ball = length(s) - 0.8;\n    ball += 0.06 * sin(s.x * 10.0 + iTime) * sin(s.y * 10.0) * sin(s.z * 10.0);   // displacement\n\n    return min(min(column, ball), p.y + 1.4);\n}\n\nvec3 calcNormal(vec3 p) {\n    vec2 e = vec2(0.001, 0.0);\n    return normalize(vec3(map(p + e.xyy) - map(p - e.xyy),\n                          map(p + e.yxy) - map(p - e.yxy),\n                          map(p + e.yyx) - map(p - e.yyx)));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    float ang = 0.3 * sin(iTime * 0.2);\n    vec3 ro = vec3(4.5 * sin(ang), 1.2, -4.5 * cos(ang));\n    vec3 fw = normalize(vec3(0.0, -0.1, 0.0) - ro);\n    vec3 rt = normalize(cross(vec3(0.0, 1.0, 0.0), fw));\n    vec3 up = cross(fw, rt);\n    vec3 rd = normalize(uv.x * rt + uv.y * up + 1.8 * fw);\n\n    float t = 0.0;\n    for (int i = 0; i < 160; i++) {\n        float d = map(ro + rd * t);\n        if (d < 0.001 || t > 20.0) break;\n        t += d * 0.6;                      // the price of bending space: smaller, safer steps\n    }\n    vec3 col = vec3(0.12, 0.13, 0.17) + 0.1 * uv.y;\n    if (t < 20.0) {\n        vec3 p = ro + rd * t;\n        vec3 n = calcNormal(p);\n        vec3 l = normalize(vec3(0.5, 0.8, -0.6));\n        vec3 albedo = p.y < -1.39 ? vec3(0.3) : (p.x < 0.0 ? vec3(0.9, 0.6, 0.25) : vec3(0.3, 0.6, 0.9));\n        float spec = pow(max(dot(n, normalize(l - rd)), 0.0), 32.0);\n        col = albedo * (max(dot(n, l), 0.0) + 0.15 * (0.5 + 0.5 * n.y)) + 0.3 * spec;\n        col = pow(col, vec3(1.0 / 2.2));\n    }\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "terrain", "label": "Example 14.6", "title": "A heightfield made of fBm, with grass, rock and snow", "chapter": 14, "passes": {"image": "float hash(vec2 p) {\n    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);\n}\n\nfloat noise(vec2 p) {\n    vec2 i = floor(p), f = fract(p);\n    vec2 u = f * f * (3.0 - 2.0 * f);\n    return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),\n               mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nfloat terrain(vec2 xz) {\n    vec2 p = xz * 0.25;\n    float sum = 0.0, amp = 0.5;\n    for (int i = 0; i < 6; i++) {\n        sum += amp * noise(p);\n        p = mat2(1.6, 1.2, -1.2, 1.6) * p;  // double the detail and turn a little, so octaves don't line up\n        amp *= 0.5;\n    }\n    return sum * 4.0 - 1.0;                 // heights from about -1 to 3\n}\n\nfloat map(vec3 p) {\n    return p.y - terrain(p.xz);             // positive above the ground\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n\n    vec3 ro = vec3(0.0, 0.0, iTime * 1.5);                    // fly forward\n    ro.y = max(terrain(ro.xz), 0.4) + 1.6;                    // stay above the ground\n    vec3 rd = normalize(vec3(uv.x, uv.y - 0.25, 1.5));\n\n    float t = 0.0;\n    for (int i = 0; i < 160; i++) {\n        float h = map(ro + rd * t);\n        if (h < 0.002 * t || t > 60.0) break;  // \"close enough\" grows with distance\n        t += h * 0.5;                          // half steps: height isn't a true distance\n    }\n\n    vec3 sunDir = normalize(vec3(0.8, 0.45, 0.6));\n    vec3 sky = mix(vec3(0.85, 0.75, 0.65), vec3(0.35, 0.5, 0.75), clamp(rd.y * 3.0, 0.0, 1.0));\n    vec3 col = sky;\n    if (t < 60.0) {\n        vec3 p = ro + rd * t;\n        vec2 e = vec2(0.02, 0.0);\n        vec3 n = normalize(vec3(terrain(p.xz - e.xy) - terrain(p.xz + e.xy), 2.0 * e.x,\n                                terrain(p.xz - e.yx) - terrain(p.xz + e.yx)));\n        vec3 rock = vec3(0.36, 0.31, 0.27), grass = vec3(0.24, 0.36, 0.14), snow = vec3(0.95);\n        vec3 albedo = mix(rock, grass, smoothstep(0.75, 0.9, n.y));      // flat = grass, steep = rock\n        albedo = mix(albedo, snow, smoothstep(1.6, 2.0, p.y + 0.3 * n.y) * smoothstep(0.55, 0.8, n.y));\n        float diff = max(dot(n, sunDir), 0.0);\n        col = albedo * (vec3(1.6, 1.3, 1.0) * diff + vec3(0.2, 0.26, 0.36));\n        col = mix(col, sky, 1.0 - exp(-0.0012 * t * t));                // haze\n    }\n    fragColor = vec4(pow(col, vec3(1.0 / 2.2)), 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "trails", "label": "Example 15.1", "title": "Light painting: each frame keeps 97% of the last", "chapter": 15, "passes": {"image": "// Image. Here iChannel0 is Buffer A's newest frame.\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.xy;\n    vec3 col = texture(iChannel0, uv).rgb;\n    col = 1.0 - exp(-col * 1.5);      // tone map: where trails overlap they glow instead of clipping\n    fragColor = vec4(col, 1.0);\n}", "buffer": "// Buffer A. Its iChannel0 is ITS OWN previous frame.\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.xy;\n    vec3 last = texture(iChannel0, uv).rgb;          // what was here last frame?\n\n    vec2 p = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    vec2 brush = 0.7 * vec2(sin(iTime * 1.3), sin(iTime * 1.9 + 1.0));      // a wandering point\n    if (iMouse.z > 0.0) brush = (iMouse.xy * 2.0 - iResolution.xy) / iResolution.y;   // or your pointer\n\n    float dotGlow = exp(-pow(length(p - brush) / 0.04, 2.0));   // a soft dot\n    vec3 ink = 0.5 + 0.5 * cos(iTime + vec3(0.0, 2.0, 4.0));    // a slowly changing color\n\n    vec3 col = last * 0.97 + ink * dotGlow * 0.4;    // keep 97% of the past, add the new\n    fragColor = vec4(col, 1.0);\n}"}, "cfg": {"bufferScale": 1, "substeps": 1, "filter": "linear"}}, {"id": "feedback", "label": "Example 15.2", "title": "Video feedback: the past, zoomed and turned", "chapter": 15, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec3 col = texture(iChannel0, fragCoord / iResolution.xy).rgb;\n    fragColor = vec4(1.0 - exp(-col), 1.0);\n}", "buffer": "// Buffer A: read the last frame zoomed and turned a little, then draw something new on top.\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.xy;\n    float aspect = iResolution.x / iResolution.y;\n\n    vec2 c = (uv - 0.5) * vec2(aspect, 1.0);       // centered, with square units (Chapter 3)\n    float a = 0.012;                               // turn a little each frame\n    c = mat2(cos(a), sin(a), -sin(a), cos(a)) * c;\n    c *= 0.985;                                    // read from closer to the center: the old image grows\n    vec3 last = texture(iChannel0, c / vec2(aspect, 1.0) + 0.5).rgb;\n\n    vec2 p = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    vec2 pos = 0.25 * vec2(cos(iTime * 1.1), sin(iTime * 1.7));   // a small ring that wanders\n    float ring = abs(length(p - pos) - 0.07);\n    vec3 ink = 0.5 + 0.5 * cos(iTime * 1.5 + vec3(0.0, 2.0, 4.0));\n\n    vec3 col = last * 0.975 + ink * 0.0015 / max(ring, 0.003);   // fade the past, add the new\n    fragColor = vec4(col, 1.0);\n}"}, "cfg": {"bufferScale": 1, "substeps": 1, "filter": "linear"}}, {"id": "life", "label": "Example 15.3", "title": "Conway's Game of Life, every cell at once", "chapter": 15, "passes": {"image": "// Image: white = alive now, color = recently alive.\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.xy;\n    vec2 cell = texture(iChannel0, uv).rg;\n    vec3 trail = 0.5 + 0.5 * cos(6.28318 * (cell.g * 0.7 + vec3(0.55, 0.65, 0.8)));\n    vec3 col = vec3(0.03, 0.035, 0.05) + trail * cell.g * 0.55 + vec3(cell.r) * 0.9;\n    fragColor = vec4(col, 1.0);\n}", "buffer": "// Buffer A: one texel = one cell. r = alive (0 or 1), g = a fading memory of life.\nfloat hash(vec2 p) {\n    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);\n}\n\nfloat alive(ivec2 p) {\n    ivec2 size = ivec2(iResolution.xy);\n    p = (p + size) % size;                       // wrap around the edges: the grid is a donut\n    return texelFetch(iChannel0, p, 0).r;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    ivec2 px = ivec2(fragCoord);                 // this cell's column and row\n\n    if (iFrame == 0) {                           // first frame: random soup, 30% alive\n        float r = step(0.7, hash(fragCoord));\n        fragColor = vec4(r, r, 0.0, 1.0);\n        return;\n    }\n\n    float n = 0.0;                               // count the 8 neighbors\n    for (int y = -1; y <= 1; y++)\n    for (int x = -1; x <= 1; x++) {\n        if (x == 0 && y == 0) continue;          // don't count yourself\n        n += alive(px + ivec2(x, y));\n    }\n\n    float me = alive(px);\n    float next = 0.0;\n    if (me > 0.5 && n > 1.5 && n < 3.5) next = 1.0;   // 2 or 3 neighbors: survive\n    if (me < 0.5 && n > 2.5 && n < 3.5) next = 1.0;   // exactly 3: born\n\n    if (iMouse.z > 0.0 && length(fragCoord - iMouse.xy) < 5.0)   // drag to scribble\n        next = step(0.5, hash(fragCoord + iTime));\n\n    float memory = max(next, texelFetch(iChannel0, px, 0).g * 0.92);\n    fragColor = vec4(next, memory, 0.0, 1.0);\n}"}, "cfg": {"bufferScale": 0.25, "substeps": 1, "filter": "nearest"}}, {"id": "turing", "label": "Example 15.4", "title": "Turing patterns: two chemicals reacting and spreading", "chapter": 15, "passes": {"image": "// Image: show chemical B as a glossy surface, lit with Chapter 13's tricks.\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.xy;\n    vec2 px = 1.0 / vec2(textureSize(iChannel0, 0));          // one buffer texel, in uv units\n    float b  = texture(iChannel0, uv).g;\n    float bx = texture(iChannel0, uv + vec2(px.x, 0.0)).g - texture(iChannel0, uv - vec2(px.x, 0.0)).g;\n    float by = texture(iChannel0, uv + vec2(0.0, px.y)).g - texture(iChannel0, uv - vec2(0.0, px.y)).g;\n\n    vec3 n = normalize(vec3(-bx, -by, 0.08));                // B as a height: finite-difference normal\n    float light = 0.55 + 0.45 * dot(n, normalize(vec3(-0.5, 0.6, 0.6)));\n    float v = smoothstep(0.08, 0.32, b);\n    vec3 col = mix(vec3(0.06, 0.08, 0.14), vec3(0.98, 0.56, 0.36), v) * light;\n    fragColor = vec4(col, 1.0);\n}", "buffer": "// Buffer A: Gray-Scott reaction-diffusion. r = chemical A, g = chemical B.\n// This pass runs 12 times per frame, because the patterns grow slowly.\nfloat hash(vec2 p) {\n    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);\n}\n\nvec2 chem(vec2 fragCoord, vec2 offset) {     // A and B at a neighboring texel, from the last step\n    return texture(iChannel0, (fragCoord + offset) / iResolution.xy).rg;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    if (iFrame == 0) {                       // start: A everywhere, a few specks of B\n        float b = step(0.985, hash(floor(fragCoord / 6.0)));\n        fragColor = vec4(1.0, b, 0.0, 1.0);\n        return;\n    }\n\n    float feed = 0.055;    // how fast A is topped up\n    float kill = 0.062;    // how fast B dies off\n    float dA = 1.0;        // how fast A spreads\n    float dB = 0.5;        // how fast B spreads\n\n    vec2 c = chem(fragCoord, vec2(0.0));\n    vec2 lap = -c                            // the Laplacian: neighbor average minus me\n        + 0.2  * (chem(fragCoord, vec2( 1.0,  0.0)) + chem(fragCoord, vec2(-1.0,  0.0))\n                + chem(fragCoord, vec2( 0.0,  1.0)) + chem(fragCoord, vec2( 0.0, -1.0)))\n        + 0.05 * (chem(fragCoord, vec2( 1.0,  1.0)) + chem(fragCoord, vec2(-1.0,  1.0))\n                + chem(fragCoord, vec2( 1.0, -1.0)) + chem(fragCoord, vec2(-1.0, -1.0)));\n\n    float a = c.r, b = c.g;\n    float reaction = a * b * b;              // A + 2B -> 3B\n    a += dA * lap.r - reaction + feed * (1.0 - a);\n    b += dB * lap.g + reaction - (kill + feed) * b;\n\n    if (iMouse.z > 0.0 && length(fragCoord - iMouse.xy) < 6.0) b = 0.9;   // drag to add B\n\n    fragColor = vec4(clamp(a, 0.0, 1.0), clamp(b, 0.0, 1.0), 0.0, 1.0);\n}"}, "cfg": {"bufferScale": 0.5, "substeps": 12, "filter": "linear"}}, {"id": "flow", "label": "Example 15.5", "title": "Dye carried by curl noise: each pixel looks upstream", "chapter": 15, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    fragColor = vec4(texture(iChannel0, fragCoord / iResolution.xy).rgb, 1.0);\n}", "buffer": "// Buffer A: colored dye, carried along by a swirling current.\nfloat hash(vec2 p) {\n    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);\n}\n\nfloat noise(vec2 p) {\n    vec2 i = floor(p), f = fract(p);\n    vec2 u = f * f * (3.0 - 2.0 * f);\n    return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),\n               mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\n// The current: noise's slope, turned a quarter turn, so it flows around hills, not up them.\nvec2 current(vec2 p) {\n    float e = 0.01;\n    float dx = noise(p + vec2(e, 0.0)) - noise(p - vec2(e, 0.0));   // slope in x\n    float dy = noise(p + vec2(0.0, e)) - noise(p - vec2(0.0, e));   // slope in y\n    return vec2(dy, -dx) / (2.0 * e);                                 // (dx, dy) turned 90°\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.xy;\n    vec2 p = fragCoord / iResolution.y * 2.5 + vec2(0.0, iTime * 0.05);\n\n    vec2 v = current(p) * 0.0015;                  // how far the water moves in one frame\n    vec3 col = texture(iChannel0, uv - v).rgb;     // where did my color come from? look upstream\n\n    vec2 q = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    for (int i = 0; i < 3; i++) {                  // three wandering taps drip in new dye\n        float fi = float(i);\n        vec2 tap = 0.6 * vec2(sin(iTime * 0.5 + fi * 2.1), cos(iTime * 0.4 + fi * 1.3));\n        vec3 ink = 0.5 + 0.5 * cos(6.28318 * (fi * 0.33 + vec3(0.0, 0.33, 0.67)));\n        col = mix(col, ink, exp(-pow(length(q - tap) / 0.03, 2.0)));\n    }\n    if (iMouse.z > 0.0) {                          // drag to drip white\n        vec2 m = (iMouse.xy * 2.0 - iResolution.xy) / iResolution.y;\n        col = mix(col, vec3(1.0), exp(-pow(length(q - m) / 0.04, 2.0)));\n    }\n\n    col = mix(col, vec3(0.04, 0.05, 0.08), 0.002); // old dye very slowly fades\n    if (iFrame == 0) col = vec3(0.04, 0.05, 0.08);\n    fragColor = vec4(col, 1.0);\n}"}, "cfg": {"bufferScale": 0.5, "substeps": 1, "filter": "linear"}}, {"id": "analyzer", "label": "Example 16.1", "title": "The audio texture: spectrum (bars) and waveform (line)", "chapter": 16, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.xy;\n\n    float level = texture(iChannel0, vec2(uv.x, 0.25)).r;   // how loud is this frequency?\n    float wave  = texture(iChannel0, vec2(uv.x, 0.75)).r;   // the raw waveform (0.5 = silence)\n\n    vec3 col = vec3(0.05, 0.05, 0.08);\n    col += vec3(1.0, 0.5, 0.2) * step(uv.y, level);                                  // bars\n    col += vec3(0.4, 0.8, 1.0) * (1.0 - smoothstep(0.0, 0.01, abs(uv.y - wave)));   // line\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {"audio": true}}, {"id": "bands", "label": "Example 16.2", "title": "Three bands, each driving one disc", "chapter": 16, "passes": {"image": "// Average loudness of the spectrum between x0 and x1 (0..1 across the texture).\nfloat band(float x0, float x1) {\n    float sum = 0.0;\n    for (int i = 0; i < 16; i++) {\n        float x = mix(x0, x1, (float(i) + 0.5) / 16.0);\n        sum += texture(iChannel0, vec2(x, 0.25)).r;\n    }\n    return sum / 16.0;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    float px = 2.0 / iResolution.y;\n\n    float bass   = band(0.0, 0.02);    // bins 0..10:   about 0 to 450 Hz\n    float mids   = band(0.02, 0.15);   // bins 10..77:  about 450 Hz to 3.3 kHz\n    float treble = band(0.15, 0.6);    // bins 77..307: about 3.3 to 13 kHz\n\n    bass = pow(bass, 3.0);             // shaping: quiet parts squashed, peaks kept (Chapter 4)\n\n    vec3 col = vec3(0.05, 0.05, 0.08) + vec3(0.25, 0.08, 0.02) * bass;   // a flash on each kick\n    float d1 = length(uv - vec2(-1.0, 0.0)) - (0.15 + 0.45 * bass);\n    float d2 = length(uv - vec2( 0.0, 0.0)) - (0.15 + 0.45 * mids);\n    float d3 = length(uv - vec2( 1.0, 0.0)) - (0.15 + 0.45 * treble);\n    col = mix(col, vec3(1.0, 0.55, 0.2), 1.0 - smoothstep(-px, px, d1));\n    col = mix(col, vec3(0.95, 0.35, 0.6), 1.0 - smoothstep(-px, px, d2));\n    col = mix(col, vec3(0.4, 0.8, 1.0), 1.0 - smoothstep(-px, px, d3));\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {"audio": true}}, {"id": "bass-piece", "label": "Example 16.3", "title": "Chapter 12's piece, with the bass driving two numbers", "chapter": 16, "passes": {"image": "vec3 palette(float t) {\n    vec3 a = vec3(0.5, 0.5, 0.5);\n    vec3 b = vec3(0.5, 0.5, 0.5);\n    vec3 c = vec3(1.0, 1.0, 1.0);\n    vec3 d = vec3(0.263, 0.416, 0.557);\n    return a + b * cos(6.28318 * (c * t + d));\n}\n\nfloat getBass() {                                     // the 8 lowest bins, averaged: 0..1\n    float sum = 0.0;\n    for (int i = 0; i < 8; i++) {\n        sum += texture(iChannel0, vec2((float(i) + 0.5) / 512.0, 0.25)).r;\n    }\n    return sum / 8.0;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    float bass = pow(getBass(), 3.0);\n\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    vec2 uv0 = uv;\n    vec3 finalColor = vec3(0.0);\n\n    for (float i = 0.0; i < 4.0; i++) {\n        uv = fract(uv * (1.5 + 0.15 * bass)) - 0.5;          // the bass pushes the tiling...\n        float d = length(uv) * exp(-length(uv0));\n        vec3 col = palette(length(uv0) + i * 0.4 + iTime * 0.4);\n        d = sin(d * 8.0 + iTime) / 8.0;\n        d = abs(d);\n        d = pow((0.01 + 0.012 * bass) / d, 1.2);              // ...and the glow\n        finalColor += col * d;\n    }\n    fragColor = vec4(finalColor, 1.0);\n}", "buffer": null}, "cfg": {"audio": true}}, {"id": "radial", "label": "Example 16.4", "title": "A circular visualizer: angle picks the frequency", "chapter": 16, "passes": {"image": "vec3 palette(float t) {\n    return 0.5 + 0.5 * cos(6.28318 * (t + vec3(0.0, 0.33, 0.67)));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    float a = atan(uv.y, uv.x);\n    float r = length(uv);\n\n    float x = abs(a) / 3.14159;                                      // 0 on the right, 1 on the left\n    float level = texture(iChannel0, vec2(x * x * 0.6, 0.25)).r;     // x * x gives the bass more room\n    float bass = pow(texture(iChannel0, vec2(0.01, 0.25)).r, 3.0);\n\n    float base = 0.42 + 0.1 * bass;                                  // the ring breathes with the bass\n    float edge = base + 0.45 * level * level;                        // each direction reaches out\n    vec3 col = palette(x * 0.8 + iTime * 0.05) * 0.008 / abs(r - edge);   // neon (Chapter 8)\n\n    float wave = texture(iChannel0, vec2(x, 0.75)).r - 0.5;          // the waveform as an inner ring\n    col += vec3(0.7, 0.85, 1.0) * 0.003 / abs(r - (base * 0.55 + wave * 0.3));\n\n    col += palette(iTime * 0.05) * bass * 0.25 * (1.0 - smoothstep(0.0, base, r));   // inner glow\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {"audio": true}}, {"id": "spectrogram", "label": "Example 16.5", "title": "A scrolling spectrogram: time across, frequency up", "chapter": 16, "passes": {"image": "// Image: color the history with a fire-like palette.\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    float v = texture(iChannel0, fragCoord / iResolution.xy).r;\n    vec3 col = vec3(pow(v, 0.8), pow(v, 2.0), pow(v, 5.0));       // dark red → orange → white\n    fragColor = vec4(col, 1.0);\n}", "buffer": "// Buffer A: scroll left by one texel, and write this frame's spectrum into the right edge.\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    if (fragCoord.x < iResolution.x - 1.0) {\n        fragColor = texelFetch(iChannel0, ivec2(fragCoord) + ivec2(1, 0), 0);   // copy my right neighbor\n        return;\n    }\n    float y = fragCoord.y / iResolution.y;                         // 0 at the bottom, 1 at the top\n    float level = texture(iChannel1, vec2(y * y * 0.7, 0.25)).r;   // iChannel1 is the sound here\n    fragColor = vec4(level, 0.0, 0.0, 1.0);\n}"}, "cfg": {"audio": true, "bufferScale": 0.5, "substeps": 1, "filter": "linear"}}, {"id": "precision", "label": "Example 17.1", "title": "The same ramp, computed near 1, 100, 1,000 and 10,000 (top to bottom)", "chapter": 17, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.xy;\n    float strip = floor(uv.y * 4.0);                     // 3 at the top .. 0 at the bottom\n\n    float big = strip == 3.0 ? 1.0 : strip == 2.0 ? 100.0 : strip == 1.0 ? 1000.0 : 10000.0;\n    big += min(iTime, 0.0);                  // always 0: stops the compiler doing the math for us\n\n    float x = big + uv.x * 0.001;            // a number near 'big', changing by just 0.001 across\n    float ramp = fract(x) * 1000.0;          // remove 'big' again, and stretch 0..0.001 to 0..1\n\n    vec3 col = vec3(ramp) * vec3(1.0, 0.75, 0.45);\n    if (fract(uv.y * 4.0) < 0.02) col = vec3(0.1);       // gaps between the strips\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "nan", "label": "Example 17.2", "title": "sqrt of negative numbers: NaN (top as-is, bottom flagged in magenta)", "chapter": 17, "passes": {"image": "void mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n\n    float v = sqrt(uv.x) * 0.8;          // on the left, uv.x < 0: sqrt has no answer, v is NaN\n    vec3 col = vec3(v) * vec3(1.0, 0.7, 0.4);          // NaN spreads into the color\n\n    if (uv.y < 0.0 && isnan(v)) col = vec3(1.0, 0.0, 1.0);   // bottom half: catch it and show it\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "test-card", "label": "Example 18.1", "title": "A test card for a home-made runner", "chapter": 18, "passes": {"image": "// Uses exactly the three uniforms the runner provides.\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    vec2 m = (iMouse.xy * 2.0 - iResolution.xy) / iResolution.y;\n    float px = 2.0 / iResolution.y;\n\n    vec3 col = 0.5 + 0.5 * cos(iTime + uv.xyx + vec3(0.0, 2.0, 4.0));   // iTime: the colors flow\n    vec2 g = abs(fract(uv * 2.0 + 0.5) - 0.5);                         // iResolution: squares stay square\n    col *= 0.85 + 0.15 * smoothstep(0.0, 2.0 * px, min(g.x, g.y));\n    float ring = abs(length(uv) - 0.8) - 0.004;                         // ...and circles stay round\n    col = mix(col, vec3(1.0), 1.0 - smoothstep(0.0, px, ring));\n    float cursor = length(uv - m) - 0.06;                               // iMouse: a dot under the pointer\n    col = mix(col, vec3(0.05), 1.0 - smoothstep(-px, px, cursor));\n\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "debug-view", "label": "Example 19.1", "title": "A debug view: every range gets its own look", "chapter": 19, "passes": {"image": "// Show any float as a color, so nothing is hidden:\n//   0..1     grey, with a band every 0.1 so you can count\n//   below 0  blue          above 1  orange\n//   infinity yellow        NaN      flashing magenta\nvec3 debugValue(float v) {\n    if (isnan(v)) return vec3(1.0, 0.0, 1.0) * step(0.5, fract(iTime * 2.0));\n    if (isinf(v)) return vec3(1.0, 1.0, 0.0);\n    if (v < 0.0) return vec3(0.1, 0.3, 1.0) * (0.45 + 0.55 * fract(-v));\n    if (v > 1.0) return vec3(1.0, 0.45, 0.1) * (0.45 + 0.55 * fract(v));\n    return vec3(v) * (0.88 + 0.12 * step(0.5, fract(v * 10.0)));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n\n    // the value under investigation: a wave that goes out of range...\n    float v = 1.5 * sin(uv.x * 2.0 + iTime) * uv.y + 0.5;\n    // ...and, on the right, square roots: of negative numbers below the middle, so NaN\n    if (uv.x > 1.2) v = sqrt(uv.y);\n\n    fragColor = vec4(debugValue(v), 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "bug-dark", "label": "Example 19.2", "title": "Bug 1: the light is up and to the left, so why is that side dark?", "chapter": 19, "passes": {"image": "// BUG: the light is up and to the left of the ball, in front of it.\n// The ball should be brightly lit from that side. It isn't.\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    vec2 p = uv / 0.8;\n\n    vec3 col = vec3(0.02);\n    float r2 = dot(p, p);\n    if (r2 < 1.0) {\n        vec3 n = vec3(p, sqrt(1.0 - r2));              // the surface normal (Chapter 7)\n        vec3 lightPos = vec3(-2.0, 2.0, 2.0);          // the light: left, up, in front\n        vec3 l = normalize(n - lightPos);              // direction toward the light\n        float diff = max(dot(n, l), 0.0);\n        col = vec3(1.0, 0.6, 0.3) * (0.03 + diff);\n    }\n    fragColor = vec4(pow(col, vec3(1.0 / 2.2)), 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "bug-shadow", "label": "Example 19.3", "title": "Bug 2: a ball should cast a shadow, but everything is dark", "chapter": 19, "passes": {"image": "// BUG: a ball on a floor, lit by a low sun, should cast one long shadow.\n// Instead, everything is in shadow.\nfloat map(vec3 p) {\n    float ball = length(p - vec3(0.0, 0.6, 0.0)) - 0.6;\n    return min(ball, p.y);                        // p.y: the floor\n}\n\nvec3 calcNormal(vec3 p) {\n    vec2 e = vec2(0.001, 0.0);\n    return normalize(vec3(map(p + e.xyy) - map(p - e.xyy),\n                          map(p + e.yxy) - map(p - e.yxy),\n                          map(p + e.yyx) - map(p - e.yyx)));\n}\n\nfloat shadow(vec3 p, vec3 l) {                    // 1 = lit, 0 = something is in the way\n    float t = 0.0;\n    for (int i = 0; i < 64; i++) {\n        float h = map(p + l * t);\n        if (h < 0.001) return 0.0;\n        t += h;\n        if (t > 10.0) break;\n    }\n    return 1.0;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n    vec3 ro = vec3(0.0, 1.5, -4.0);\n    vec3 rd = normalize(vec3(uv.x, uv.y - 0.3, 1.6));\n\n    float t = 0.0;\n    for (int i = 0; i < 100; i++) {\n        float d = map(ro + rd * t);\n        if (d < 0.001 || t > 20.0) break;\n        t += d;\n    }\n    vec3 col = vec3(0.55, 0.65, 0.8);\n    if (t < 20.0) {\n        vec3 p = ro + rd * t;\n        vec3 n = calcNormal(p);\n        vec3 l = normalize(vec3(-0.7, 0.45, -0.3));   // toward a low sun\n        float diff = max(dot(n, l), 0.0) * shadow(p, l);\n        col = vec3(0.85, 0.75, 0.6) * (diff + 0.1 * (0.5 + 0.5 * n.y));\n    }\n    fragColor = vec4(pow(col, vec3(1.0 / 2.2)), 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "bug-washed", "label": "Example 19.4", "title": "Bug 3: six colored rings, so why is it mostly white?", "chapter": 19, "passes": {"image": "// BUG: six glowing rings in six different colors. But it's mostly a white blur.\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;\n\n    vec3 col = vec3(0.0);\n    for (int i = 0; i < 6; i++) {\n        float fi = float(i);\n        vec2 c = 0.45 * vec2(cos(iTime * 0.5 + fi), sin(iTime * 0.7 + fi * 1.3));\n        float d = abs(length(uv - c) - 0.3);\n        vec3 tint = 0.5 + 0.5 * cos(fi + vec3(0.0, 2.0, 4.0));\n        col += tint * 0.06 / d;                  // each ring adds its glow\n    }\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "p5-filter", "label": "Example 20.1", "title": "A filter: reading a drawing at bent coordinates", "chapter": 20, "passes": {"image": "// Stand-in for what p5 draws. In the p5 sketch, replace drawing(bent)\n// with texture(iChannel0, bent).rgb and draw anything you like in draw().\nvec3 drawing(vec2 uv) {\n    float aspect = iResolution.x / iResolution.y;\n    vec3 col = vec3(0.95, 0.93, 0.88);                         // paper\n    for (int i = 0; i < 5; i++) {\n        float fi = float(i);\n        vec2 c = 0.5 + 0.3 * vec2(sin(iTime * 0.6 + fi * 1.7), cos(iTime * 0.5 + fi * 2.3));\n        float r = 0.08 + 0.03 * sin(fi * 3.1);\n        vec3 ink = 0.5 + 0.5 * cos(6.28318 * (fi * 0.17 + vec3(0.0, 0.33, 0.67)));\n        float d = length((uv - c) * vec2(aspect, 1.0)) - r;\n        col = mix(col, ink, 1.0 - smoothstep(0.0, 0.006, d));\n    }\n    return col;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = fragCoord / iResolution.xy;                      // 0..1, like texture coordinates\n    vec2 c = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);\n    float r = length(c);\n\n    // ripples spreading from the center push each lookup in or out a little\n    float push = 0.015 * sin(r * 40.0 - iTime * 4.0) * exp(-r * 2.0);\n    vec2 bent = uv + (c / max(r, 1e-4)) * push / vec2(iResolution.x / iResolution.y, 1.0);\n\n    vec3 col = drawing(bent);\n    // vec3 col = drawing(uv);                                 // compare: the plain drawing\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}, {"id": "toolkit", "label": "Example 20.2", "title": "Your toolkit: the course's helpers and a starter piece", "chapter": 20, "passes": {"image": "// Your toolkit: the course in one file. Delete what you don't use.\n\nmat2 rot(float a) {                                  // Chapter 9: rot(a) * p turns p by a\n    float c = cos(a), s = sin(a);\n    return mat2(c, s, -s, c);\n}\n\nvec3 palette(float t) {                              // Chapter 6: put your favorite a, b, c, d here\n    vec3 a = vec3(0.5), b = vec3(0.5), c = vec3(1.0);\n    vec3 d = vec3(0.263, 0.416, 0.557);\n    return a + b * cos(6.28318 * (c * t + d));\n}\n\nfloat hash(vec2 p) {                                 // Chapter 11: a random number per input\n    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);\n}\n\nfloat noise(vec2 p) {                                // Chapter 11: smooth value noise\n    vec2 i = floor(p), f = fract(p);\n    vec2 u = f * f * (3.0 - 2.0 * f);\n    return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),\n               mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nfloat fbm(vec2 p) {                                  // Chapter 11: octaves of noise\n    float sum = 0.0, amp = 0.5;\n    for (int i = 0; i < 5; i++) {\n        sum += amp * noise(p);\n        p = rot(0.5) * p * 2.0;                      // turn each octave so they don't line up\n        amp *= 0.5;\n    }\n    return sum;\n}\n\nfloat sdBox(vec2 p, vec2 b) {                        // Chapter 8: box distance\n    vec2 q = abs(p) - b;\n    return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0);\n}\n\nfloat smin(float a, float b, float k) {              // Chapter 8: melt two shapes together\n    float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);\n    return mix(b, a, h) - k * h * (1.0 - h);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;   // Chapter 3\n    float px = 2.0 / iResolution.y;                                 // one pixel, for smooth edges\n\n    // ── start here ──\n    vec2 p = rot(iTime * 0.05) * uv;\n    float n = fbm(p * 2.0 + fbm(p * 2.0 + iTime * 0.1));    // a quick domain warp (Chapter 11)\n    float d = sdBox(p, vec2(0.6));\n    vec3 col = palette(n + iTime * 0.05) * (0.25 + n);\n    col += vec3(1.0, 0.8, 0.6) * 0.006 / abs(d);            // a neon frame (Chapter 8)\n\n    col = 1.0 - exp(-col);                                  // tone map (Chapter 6)\n    fragColor = vec4(col, 1.0);\n}", "buffer": null}, "cfg": {}}];
